* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * **			                  **      A P P L E   I I g s   I N S T A L L E R   P R O G R A M   V  2 . 0     **                                                                             **                              by "Jay" Schaffer                              **                               and  Ron Lichty                               **			                  **  Copyright Apple Computer, Inc. 1987-1991              All Rights Reserved  **			                  ** * * * * * * * * *	* * * * * * * * * *	* * * * * * * * * *	* * * * * * * * * *	Print Push	Print Off	Include 'Installer.Equates'	Print Pop	Seg 'Main'	SegAttr Static* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *** Small but commonly called procedures** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *CursorWatchOn	Proc Export	ldx #WaitCursor	; Switch to the "watch" cursor.	jsl ToolLocator	rts	EndPCursorArrowOn	Proc Export	ldx #InitCursor	; Switch cursor arrow back on.	jsl ToolLocator	rts	EndP* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *CheckCharacter	Proc Export** Description:	CheckCharacter is a subroutine to examine the*	characteristics word obtained during a D_Info call*	and activate/deactivate the EJECT button accordingly,*	as well as enable/disable the ERASE DISK menu item.*	The ERASE DISK menu item is also disabled if the*	target disk is the boot disk or the launch disk.** Inputs:*	none** Outputs:*	none** External Refs:	Import CurrentVolBuf	Import D_DeviceID	Import D_Info_Parms	Import DialogFlag	Import DisableEraseDiskMenu	Import EjectControl	Import Eject2Control	Import EnableEraseDiskMenu	Import GStrCompare	Import LaunchVolStrBuffer	Import VolStrBuffer** Entry Points:*	none** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	lda D_Info_Parms+8	; Check the characteristics	and #FormatableMedia ;  of the current drive	beq notEraseable	; bra if not formatable; disk is formattable: enable Erase Disk menu item? Check for boot or launch disk.	pha	; word space for result	pea CurrentVolBuf>>16 ; compare target	pea |CurrentVolBuf	pea VolStrBuffer>>16 ;  ...to boot volume	pea |VolStrBuffer	jsl GStrCompare	pla	beq notEraseable	; bra: don't erase boot volume (files open)		pha	; word space for result	pea CurrentVolBuf>>16 ; compare target	pea |CurrentVolBuf	pea LaunchVolStrBuffer>>16 ;  ...to launch volume	pea |LaunchVolStrBuffer	jsl GStrCompare	pla	beq notEraseable	; bra: don't erase launch volume (files open)		jsr EnableEraseDiskMenu	bra checkEject; disable Erase Disk menu itemnotEraseable	jsr DisableEraseDiskMenucheckEject	lda D_Info_Parms+8	; Check the characteristics	and #RemovableMedia	;  of the current drive	beq @NotEjectable	; If media is not removable...	lda D_Info_Parms+8	and #RAMorROMdisk	bne @NotEjectable	; bra if media is RAM or ROM disk	lda D_Info_Parms+20	; Check device identification	beq @NotEjectable	; ID = zero---means it's a DISK ][	cmp #AppleShareFileServ ; Dim the Eject button on any	beq @NotEjectable	    ; kind of file server.	cmp #FileServer	beq @NotEjectable	lda #Active	; Else, activate the Eject button	bra @2@NotEjectable	lda #Inactive	; Dim the Eject button@2	bit DialogFlag	; Which dialog is running?	bmi @3	jsr EjectControl	rts@3	jsr Eject2Control	rts	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *FlushEventQueue	Proc Export** Description:	FlushEventQueue is called by any routine that should not*	accept double clicks.** Inputs:	none** Outputs:	none** External Refs:	none** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	pha	; Flush the event queue	pea emKeyDown+\	    emUpdate+\	    emMouseUp+\	    emMouseDown+\	    emDeskAcc	pea 0000	; Flush everything (StopMask)	ldx #FlushEvents	jsl ToolLocator	pla	; Disregard result	rtl	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *Dir_Reader	Proc Export** Description:	Dir_Reader will find all the files within a specified*	directory.  A file type may be specified if only files of a*	given type are of interest.  A list of member pointers and*	members in List Manager format is built and the handle to*	the list and the number of members is returned.**	The FileType word shall contain a ProDOS file type in the*	low order byte.  If bit 15 is set, all files will be listed*	and the file type will be ignored.  If bit 14 is set, all*	files will be listed with those of the desired file type*	marked active and the rest inactive.** Inputs:	Push five parameters on the stack:*	   Room for handle to results buffer     (4 bytes)*	   Room for number of members value      (2 bytes)*	   UserID (so we can call MemMgr)        (2 bytes)*	   <CurDirPtr (current directory pointer)(4 bytes)*	   File type (See comments above)        (2 bytes)** Outputs:	Pull two parameters from stack:*	   Number of members                    (2 bytes)*	   Handle to buffer containing results  (4 bytes)*	   (Results will be in List Manager format.)** External Refs:	Import Allocate	Import BuildDirName	Import CursorArrowOn	Import CursorWatchOn	Import DeRef	Import DeReference	Import GetCurDirPtr	Import GetPfxName	Import GetPfxParms	Import UnlockCurDirHdl	Import VNameBuffer** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *; Local EquatesMemoryHandle	equ 23	; 4-byte Handle to member bufferNoOfMembers	equ 21	; 2-byte Number of members (result)UserID	equ 19	; 2-byte user IDCurDirPointer	equ 15	; 4-byte ptr to Directory name; Class 1 input; lockedFileType	equ 13	; 2-byte file typeReturnAddress	equ 11	; 2-byte return addressPointer	equ 7	; 4-byte pointerFileNamePtr	equ 3	; 4-byte pointer; D-Reg Store 	equ 1	; 2-byte D-reg storage; Push some dummy long words on the stack so we can use them for direct-page; pointers	pha	pha	pha	pha	phd	; Save the Direct-Reg; Relocate our direct page to the stack	area so we can conveniently work with; the caller's parameters	tsc	; Make the stack our direct-page	tcd; Initialize variables	stz NoOfMembers	stz OurCounter	stz MemorySize	stz MemorySize+2; Get a handle from	the Memory Manager but don't allocate any space yet.	lda #0000	; Size of block needed	jsl Allocate	stx MemoryHandle	; Store handle to results buffer	sty MemoryHandle+2	;    (not locked); Set up the pathname pointer in the OPEN parameter table to point to the; caller's directory name and OPEN the requested directory	lda #0003	; pCount for Open call	sta Open_Parm	lda CurDirPointer	; already locked	sta OpenPathname	lda CurDirPointer+2	sta OpenPathname+2@1	jsl GSOS	dc.w Open	dc.l Open_Parm	bcc Continue1	jsr AskForVolume	bcc @1	brl Exit; Move the reference number to the Get_Dir_Parm tableContinue1	lda OpenRefNum	sta GetDirRefNum	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .;; Get a directory entry - The Main Loop; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .Next_Entry	jsl GSOS	dc.w Get_Dir_Entry	dc.l Get_Dir_Parm	bcc Continue2	cmp #EndOfDir	; No more entries?	bne Oops	brl BuildPointersOops		; We're assuming that if it isn't an	jsr AskForVolume	;  "OutOfEntries" error, it MUST be	bcc Next_Entry	;  a "VolumeNotFound"!!!	brl Exit; Check to see that	it is of a filetype	that the caller is interested in and; if it isn't, go back and get the next entryContinue2	bit Filetype	; Does caller want all filetypes?	bmi Continue3	; Yes!	bvs Continue3	; Yes!	lda Filetype	and #$00FF	cmp File_Type	bne Next_EntryContinue3	lda Access	; Check if file is visible	and #%0000000000000100	bne Next_Entry	; File is invisible; Call the Memory Manager to make room in a buffer for it.;       Save the current memory size as OldMemorySize for later use as;       the offset into the buffer for the current entry	clc	lda MemorySize	sta OldMemorySize	adc LengthWord	adc #0002	; One extra byte for a flag...	sta MemorySize	;  ...and one for the length byte	tax	lda MemorySize+2	sta OldMemorySize+2	adc #0000	sta MemorySize+2	pha	; Push NewSize	phx	pei MemoryHandle+2	; Push the Handle	pei MemoryHandle	ldx #SetHandleSize	jsl ToolLocator; Dereference the handle, add on the index to the next entry, get the filename,; move the filename	into the buffer, and go get the next entry	jsr DeRefHandle	; MemoryHandle --> Pointer (not locked)	clc	lda Pointer	adc OldMemorySize	sta Pointer	lda Pointer+2	adc OldMemorySize+2	sta Pointer+2;       If we reverse the two bytes of the LengthWord, we can move over;       one position and use it as a length byte.	lda LengthWord	xba	sta LengthWord	sep #$0030	; (Use 8-bit memory	to move bytes)	LongA Off	LongI Off	ldy EntryPath	; Move the pathnameMoveLoop	lda EntryPath,y	sta [Pointer],y	dey	bpl MoveLoop; Now, figure out if this should be active or inactive.; Bit 6, a List Manager ÒinactiveÓ flag will be transferred to memFlag in Member Record.; Bit 0, our inactive folder flag, will remain at end of string for display routine to use.	bit Filetype+1	bmi ItsActive	; bit 7 on = all active	lda File_Type	; get fileÕs type	cmp Filetype	; compare to input parameter	beq ItsActive	; if the same, then consider it active regardlessItsInactive	lda #%01000000	; else doesnÕt match param: mark it inactive	ldx File_Type	; If it's an inactive folder, set the	cpx #SubDirectory	;  lo-bit as a flag for our display routine	bne MarkIt	lda #%01000001	; Mark it inactive	bra MarkItItsActive	lda Access	; Now, check privileges	and #%00000001	; Must be readable	cmp #%00000001	bne ItsInactive	lda #%00000000	; Mark it activeMarkIt	ldy EntryPath	; Put the flag at the end of the string for now	iny	sta [Pointer],y	LongI On	; (Finished moving bytes)	LongA On	rep #$0030	inc NoOfMembers	; Keep a running count of files	brl Next_Entry	; Go get the next entry; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .;; End of Main Directory Reader Loop; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	Eject; Before doing anything else, CLOSE the	directory and determine if; we got any entries at allBuildPointers	lda #0001	; pCount for Close call	sta Open_Parm	jsl GSOS	dc.w Close	dc.l Open_Parm	; Close the directory using OpenRefNum	lda NoOfMembers	; Are there none?	bne Continue4; There are NO members, so no list is needed.  Simply pass back; zero as the number of members in the list.	brl Finished; Build the List MgrÕs Member Record list (4 byte pointer to string, 1 memFlag byte);       Re-size the memory segment to make room for the pointersContinue4	lda MemorySize	sta OldMemorySize	lda MemorySize+2	sta OldMemorySize+2	lda NoOfMembers	; Need five bytes per member	asl a	;  ( X2 ) \	asl a	;  ( X2 )  > = X5	clc	;         /	adc NoOfMembers	;  ( +1 )/	sta PointerSize	; (Need this later for block move call); NOTE LIMIT:  1 word (64K) of pointers and filenames; NOTE: this limit is implicit in putting them in the same no-cross-bank block anyway	clc	adc MemorySize	sta MemorySize	tax	lda #0000	adc MemorySize+2	sta MemorySize+2	pha	; Push NewSize	phx	pei MemoryHandle+2	pei MemoryHandle	ldx #SetHandleSize	jsl ToolLocator;             Move all the file name strings up to the top of the segment	ldx MemoryHandle+2	lda MemoryHandle	jsl DeRef	; Dereference the handle and lock it	sta Pointer	stx Pointer+2	phx	; Push source address	pha	clc	adc PointerSize	; (Pointer + PointerSize)	sta FileNamePtr	tay	txa	; (Pointer+2)	adc #0000	sta FileNamePtr+2	pha	; Push destination address (FileNamePtr)	phy	lda OldMemorySize+2	; Push number of bytes	pha	lda OldMemorySize	pha	ldx #BlockMove	; source & dest of move based on now-locked hdl	jsl ToolLocator;       Build the pointer list	ldy #0000PointerLoop	lda FileNamePtr	; Move the 4-byte pointer	sta [Pointer],y	iny	iny	lda FileNamePtr+2	sta [Pointer],y	iny	iny;       Now, move that extra 'flag' byte we tacked on to the;       end of each string, on to the end of each pointer;       (but not bit 0, which is our disabled folder flag, not a List Mgr flag).	lda #0000	; Clear both bytes of A-reg	sep #$20	LongA Off	phy	; Save the Y register	lda [FileNamePtr]	; Get the length byte...	tay	;  ...put it in Y-reg...	iny	;  ...and set it to	the 'flag' byte	lda [FileNamePtr],y ; Get the 'Flag'...	ply	; Restore the Y register	and #$FE	; and out low bit: itÕs our flag, not List MgrÕs	sta [Pointer],y	; Put flag at end of pointer	rep #$20	LongA On	inc OurCounter	lda OurCounter	cmp NoOfMembers	beq Finished;       Update all the pointers and stuff for next entry	lda [FileNamePtr]	; Get length byte	and #$00FF	; Mask off first character	clc	adc FileNamePtr	adc #0002	; Don't forget length & flag bytes	sta FileNamePtr	lda #0000	adc FileNamePtr+2	sta FileNamePtr+2	iny	bra PointerLoop; Now build a name (shortened, if necessary) in CurrentDir to be displayed.Finished	jsr BuildDirName	jsl UnlockCurDirHdl; Fix the stack by moving the return address down next to the results and; adjusting the stack pointer	lda #0000	; No errorsExit	tax	; Save error code	lda ReturnAddress	sta NoOfMembers-2	pld	; Restore caller's Direct-Reg	tsc	; Fix the stack pointer by 'removing'	clc	;  our work space and extra parameters	adc #0016	tcs	txa	; Restore the error code	cmp #0001	; Set/clear c-flag depending on error code	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .;; ProDOS16 parameter tables and local storage;Open_Parm	dc.w 0003	; pCountOpenRefNum	dc.w 0000	; Reference NumberOpenPathname	dc.l 00000000	; Path Name Pointer	dc.l 00000000	; I/O Buffer PointerGet_Dir_Parm	dc.w 0014	; pCountGetDirRefNum	dc.w 0000	; Reference Number	dc.w 0000	; (reserved, must be zero)	dc.w 0001	; Base	dc.w 0001	; DisplacementEntry_Path	dc.l NameBuffer	; Path Name PointerEntry_Num	dc.w 0000	; Entry NumberFile_Type	dc.w 0000	; File Type	dc.l 00000000	; EOF	dc.l 00000000	; Block Count	dcb.b 8,0000000000000000 ; Creation Date and Time	dcb.b 8,0000000000000000 ; Modification Date and TimeAccess	dc.w 0000	; Access	dc.l 00000000	; Aux Type	dc.w 0000	; File System IDNameBuffer	dc.w 35	; 35 bytes  (big enough for AppleShare)LengthWord	ds.b 1	; Length word + pathnameEntryPath	ds.b 32MemorySize	ds.b 4	; Size of memory blockOldMemorySize	ds.b 4	; Offset to next buffer entryPointerSize	ds.b 2	; Size of seg holding member pointersOurCounter	ds.b 2	; Loop counter	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .DeRefHandle;; Local subroutine to dereference the handle to the filename buffer;;    Inputs:  None (Handle expected in 'MemoryHandle');;   Outputs:  None (Pointer stored in 'Pointer'); . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	pei MemoryHandle+2	; Dereference the handle	pei MemoryHandle	jsl Dereference	pla	sta Pointer	pla	sta Pointer+2	rts	Eject;................................................................AskForVolume;; Local subroutine to ask user to insert the needed volume if it ; cannot be found.  (This routine is needed here because I wanted; to make Dir_Reader as completely self contained as possible.;................................................................		;¥¥¥¥¥¥¥¥	lda #VolumeNotFound	;       ¥	sec	;       ¥	rts	;       ¥;¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥¥	Import SimpleKeyFilter	Import VolumeTemplate	pha	; Save the GrafPort	pha	;  (Don't pull the result.  Leave it on the	ldx #GetPort	;   stack for _SetPort call upon exit.)	jsl ToolLocator; The address of the pathname used when the "Volume not Found" error; was encountered is in "Pathname".	ldx OpenPathname	ldy OpenPathname+2	stx Pointer	sty Pointer+2; Clear the NameBuffer to all spaces	ldy #0014	lda #$2020	; (two spaces)@0	sta VNameBuffer,y	dey	dey	bpl @0; If the pathname begins with a number, make the appropriate Get_Prefix; call to get a pathname that will include the volume name.	sep #$0030	LongA Off	LongI Off	ldy #01	lda [Pointer],y	cmp #'0'	bcc @1	cmp #'9'+1	bcs @1	LongI On	LongA On	rep #$0030	and #%0000000000001111 ; Convert ASCII digit 0..8 to hex	sta GetPfxParms+2	; Store prefix number	bra @2; If the pathname does not begin with a SeparatorChar the volume name; is not included.  Make a Get_Prefix call to get a pathname that will; include the volume name and move the name to our message buffer.	LongA Off	LongI Off@1	cmp #SeparatorChar	beq @3	LongI On	LongA On	rep #$0030	stz GetPfxParms+2	; Ask for prefix number zero@2	jsl GSOS	dc.w Get_Prefix	dc.l GetPfxParms	lda GetPfxName-1	xba	sta GetPfxName-1	sep #$0030	longA Off	LongI Off	ldy #1	; Skip over length byte	lda GetPfxName,y	sta VNAmeBuffer-1,y	iny	; Skip over leading slash@25	lda GetPfxName,y	; Search for 2nd slash	cmp #SeparatorChar	beq @5	sta VNameBuffer-1,y	iny	bra @25; We have a name that includes the desired volume name.  Move only the; volume name to our name buffer@3	sta VNameBuffer-1,y@4	iny	lda [Pointer],y	cmp #SeparatorChar	beq @5	sta VNameBuffer-1,y	tya	cmp [Pointer]	bne @4@5	LongI On	LongA On	rep #$0030; Present the dialog to the user.	jsr CursorArrowOn	pha	; Space for result	pea VolumeTemplate>>16 ; Pointer to template	pea |VolumeTemplate	pea SimpleKeyFilter>>16 ; Filter procedure	pea |SimpleKeyFilter	ldx #Alert	jsl ToolLocator	jsr CursorWatchOn	; Put the watch cursor back up	pla	; Get ModalDialog's response	cmp #0001	beq HitOK; If user hit cancel, return with the "Volume not Found" error cade in; the A-reg and the carry set since we know the error still exists.; Otherwise, zero the A-reg and clear the carry so the call that sent; us here can be attempted again.	ldx #SetPort	; ("GrafPort" is still on the stack.)	jsl ToolLocator	lda #VolumeNotFound	sec	rtsHitOK	ldx #SetPort	; ("GrafPort" is still on the stack.)	jsl ToolLocator	lda #0000	clc	rts	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *NewList	ProcName Export** Description:	Folder List:*	NewList is a subroutine to dump the previous memory segment*	and build a new list in a new memory segment.** Inputs:	None  (Uses MyID, CurDirectory, ListFileType)** Outputs:	None  (Stores ListSize2)** External Refs:	Import GetCurDirPtr	Import GStrAsC1Inp	Import AppFolderListHdl	Import ListSize2	Import MyID	Import UnlockCurDirHdl** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *; Begin by dumping the previous memory segment.  If this is	the first time,; there is NO previous memory segment to dump.  In that case, AppFolderListHdl; will still point to a null pointer and _DisposeHandle WILL return an error!; Just ignore it!	lda AppFolderListHdl+2	pha	lda AppFolderListHdl	pha	ldx #DisposeHandle	jsl ToolLocator	jsl GetCurDirPtr	; Get the pointer to the GStr buffer	pha	; Room for result	pha	pei <CurDirPtr+2	; Get the pointer to the sub-string	pei <CurDirPtr	;  that constitutes a Class 1 input	jsl GStrAsC1Inp	;  string.	plx	ply 	pha	; Room for List Handle	pha	pha	; Room for No. of members	lda MyID	pha	; My ID for calling Memory Manager	phy	; Pointer to directory name	phx	pea ListFileType	; File type of interest	jsr Dir_Reader	plx	; Don't change A-reg...it has an error code	stx ListSize2	;  value in it.	plx	stx AppFolderListHdl	plx	stx AppFolderListHdl+2	pha	; Save error code	jsl UnlockCurDirHdl	pla	; Restore error code	rts	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *MakeNewList	ProcName Export**  Description:	Folder List:*	MakeNewList will build a new list for the List Manager,*	but does NOT display it.  (Uses CurDirectory.)                            ***  Inputs:	None**  Outputs:	None** External Refs:	Import DeReference	Import DirSelReq	Import DispCurrentDir	Import DispCurrentVol	Import DiskControl	Import GetCurDirPtr	Import AppFolderListHdl	Import ListStart2	Import NewList2Call	Import NoMemberSelected	Import OpenControl	Import SelectListCtlHdl	Import SelectWindow	Import WindowSetUpComplete	Import UnlockCurDirHdl**  Side Effects:	The old memory segment is dumped and a new segment is*	obtained to hold the new list.** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	jsl GetCurDirPtr	ldy #0002	lda [<CurDirPtr],y	; If current directory is null, we're done	php	; Save processor status	jsl UnlockCurDirHdl	plp	; Restore processor status	bne @1	rtl; We've got something to do!; but first handle data bank register in case we were called from another bank@1	phb	phk	plb	bit DirSelReq	; Are we displaying	directory or volume?	bmi BuildList	lda #Inactive	; Deactivate application folder selection	jsr SelectWindow	;  window, its scroll bar, and PopUp menu	brl Exit;BuildList	jsr NewList	; Build the list & store ListSize2	bcc GoAhead	brl Exit;GoAhead	jsr NewList2Call	lda AppFolderListHdl+2	; De-reference the handle	pha	lda AppFolderListHdl	pha	jsl Dereference	pla	sta <ZPTemp	;  and put pointer into <ZPTemp	pla	sta <ZPTemp+2; The NewList tool is TOO dumb to know that an inactive member cannot be; selected!  So, we've got to look at the flags byte of the first member and; determine if it is active and handle this stuff ourselves!	bne GotAPointer	; If de-referencing	the handle returned	lda <ZPTemp	;  a null pointer, we have a null list	beq NoMemberGotAPointer	clc	ror NoMemberSelected	ldy #0004	; Check the 'active' bit	lda [<ZPTemp],y	and #%0000000001000000	beq ItsOKNoMember	sec	ror NoMemberSelected	lda #Inactive	; No mem selected--make OPEN inactive	jsr OpenControl	stz ListStart2	; No member selected	bra ItsNotOKItsOK	lda [<ZPTemp],y	; Mark first member as "selected"	ora #%0000000010000000	sta [<ZPTemp],y	lda #Active	; activate OPEN button	jsr OpenControl	lda #0001	; First member to be selected 	sta ListStart2ItsNotOK		bit WindowSetUpComplete	bpl Exit	lda #Active	; set it to normal (not dimmed)	jsr DiskControlExit	plb	; restore the previous data bank	rtl	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *DeReference	Proc Export** Description:	DeReference is a general purpose handle de-referencing*	subroutine.  Simply push a handle and get back a pointer.** Inputs:	Push one LongWord on the stack containing the handle to be*	de-referenced.** Outputs:	Pull one LongWord from the stack which will contain the*	pointer associated with the above handle.** External Refs:	none** Side Effects:	A, X, and Y are scrambled.** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *; D-Reg Store	equ $01	; 2-bytes to save Direct-Register; ReturnAddress	equ $03	; 3-byte return addressPointer	equ $06	; 4-byte parameterHandle	equ $06	; 4-byte parameter;	phd	; Save the caller's Direct-Register value	tsc	; Move the stack pointer...	tcd	;   ...into the Direct-Register;; The stack is now our zero-page;	lda [Handle]	; Get the contents of the handle	tax	ldy #2	lda [Handle],y	stx Pointer	;   and store in Pointer	sta Pointer+2;; Restore the caller's Direct-Register, and we're finished.;	pld	rtl;	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *DeRef	Proc Export** Description:	DeRef locks and dereferences the handle passed in A, X (hi).*	Results are passed back in A, X (hi).  (Stolen from HodgePodge.)** Inputs:	A-reg and X-reg (hi) contain handle to dereference.** Outputs:	A-reg and X-reg (hi) contain pointer.** External Refs:	Import MyZP** Side Effects:	** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	tay	phd	lda >MyZP	tcd	sty <ZPDeRef	; Store the handle	stx <ZPDeRef+2	ldy #4	; Lock the handle	lda [<ZPDeRef],y	ora #$8000	sta [<ZPDeRef],y	dey	; Retrieve the pointer	dey	lda [<ZPDeRef],y	tax	lda [<ZPDeRef]	pld	rtl	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *CheckScript	ProcName Export** Description:	CheckScript checks the current script file and determines*	if it requires directory selection and then activates*	and/or deactivates controls and StaticText as needed.** Inputs:	none** Outputs:	none** External Refs:	import CurrentVol	Import DirSelReq	Import DispDir2Update	Import DispDisk2Update	Import GetCurDirPtr	Import InstallRemoveMode	Import NewFolderActive	Import NewFolderDim	Import NoMemberSelected	Import NoVolumes	Import NumOfSelections	Import OpenControl	Import ResizeCurDirBuf	Import SelectWindow	Import UnlockCurDirHdl	Import UpdatePopUp** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *; First simply check to see if there are any selections	lda NumOfSelections	beq NoSelectionExit; Check DirSelReq to see whether the script needs a directory name.	bit DirSelReq	bmi Directory	; hi-bit set=directory name required; hi-bit clear=The script does NOT require a directory name.;       Erase 'Folder to Update:' and the Directory Name.  Then display 'Disk;       to Update:' and the Volume NameNoDirectory	jsr DispDisk2Update;       Deactivate controls associated with directory selectionNoSelectionExit	jsr NewFolderDim	lda #Inactive	jsr OpenControl;       Deactivate the directory selection window and special menu	lda #Inactive	jsr SelectWindow;       Set the pop-up menu back to the first level and set current directory;       back to the volume name.	jsl GetCurDirPtr	lda CurrentVol	; Set CurDirectory back to the Volume name	ldy #0002	sta [<CurDirPtr],y	jsl ResizeCurDirBuf	; Resize the memory	jsl UnlockCurDirHdl	jsr UpdatePopUp	; Update the PopUp menu	rts; Script DOES require a directory name;       Erase 'Disk to Update:' and the Volume Name.  Then display 'Directory;       to Update:' and the Directory NameDirectory	jsr DispDir2Update;       Activate the OPEN only if some destination folder is selected	bit NoMemberSelected ; Activate ONLY if something is selected	bmi @10	lda #Active	bra @20@10	lda #Inactive@20	jsr OpenControl;       Activate the NEW FOLDER button only if non-write-protected volume is on line	bit NoVolumes	; Activate ONLY if there's a volume on-line	bmi @50	lda InstallRemoveMode ; Activate INSTALL if appropriate	and #bWriteProtect	bne @50	  ; bra if set, should be inactive	jsr NewFolderActive@50;       Activate the directory selection window and special menu	lda #Active	jsr SelectWindow	jsr UpdatePopUp	rts	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *ReBootDialog	Proc Export** Description:	ReBootDialog will display a dialog notifying the user that*	they have replaced system files on the boot disk and must*	re-boot the system.  If this routine returns to the caller,*	it is because they have cancelled the quit.** Inputs:	none** Outputs:	none** External Refs:	Export DrawCautionIcon	Export DrawStopIcon	Import CancelStr	Import CautionIconPtr	Import EndReBootMsg	Import QuitFlag	Import ReBootStr	Import ReBootMsg	Import SimpleKeyFilter	Import StopIconPtr** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	pha	; Space for result	pea ReBootTemplate>>16 ; Pointer to template	pea |ReBootTemplate	pea SimpleKeyFilter>>16 ; Filter procedure	pea |SimpleKeyFilter	ldx #Alert	jsl ToolLocator	pla	; Get the item hit ID	cmp #0002	; Clear the QuitFlag if Cancel	bcc @ReBootSystem	; ReBoot if Restart hit	lda QuitFlag	and #%0111111111111111 ; Clear "Quit" bit, preserve 	sta QuitFlag	;  "ReBoot" bit	rts@ReBootSystem	jsl GSOS	   ; This call never returns	dc.w OS_ShutDown	dc.l OSShutDownParm; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .OSShutDownParm	dc.w 1	   ; pCount	dc.w %0000000000000001 ; shutdown_flag  ReBoot w/RAM disk intactrWidth    equ 411rHeight   equ 62rTop      equ (200/2)-(rHeight/2)rLeft     equ (640/2)-(rWidth/2)+1rBottom   equ rTop+rHeightrRight    equ rLeft+rWidthReBootTemplate	dc.w rTop,rLeft,rBottom,rRight	dc.w 5555	; ID	dc.b $81	dc.b $81	dc.b $81	dc.b $81	dc.l ReBootButton	dc.l CancelButton	dc.l ReBootMessage	dc.l Icon	dc.l 00000000ReBootButton	dc.w 1	; ID	dc.w rHeight-20,rWidth-146  ; Bounds rect for button	dc.w rHeight-8,rWidth-22	dc.w ButtonItem	; Type	dc.l ReBootStr	; Item descriptor	dc.w 0000	; Item value	dc.w 0001	; Item flag	dc.l 00000000	; Item colorCancelButton	dc.w 2	; ID	dc.w rHeight-20,rWidth-277  ; Bounds rect for button	dc.w rHeight-8,rWidth-167	dc.w ButtonItem	; Type	dc.l CancelStr	; Item descriptor	dc.w 0000	; Item value	dc.w 0000	; Item flag	dc.l 00000000	; Item colorReBootMessage	dc.w 3333	; ID	dc.w 7,81,rHeight-28,rWidth-10  ; Bounds rect for text	dc.w LongStatText2+ItemDisable ; Type	dc.l ReBootMsg	; Item descriptor	dc.w EndReBootMsg-ReBootMsg ; Item value	dc.w 0000	; Item flag	dc.l 00000000	; Item colorIcon	dc.w 0004		; ItemID	dc.w 8,16,27,74		; ItemRect	dc.w UserItem+ItemDisable ; ItemType	dc.l DrawStopIcon	; ItemDescr	dc.w 0000		; ItemValue	dc.w 0000		; ItemFlag	dc.l 00000000		; ItemColor	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .DrawStopIcon	Name;; Draws the stop sign icon into the Dialog.; DrawCautionIcon draws the caution sign icon into the Dialog.; Called only by Dialog Manager, when itÕs implementing various dialog templates.; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	lda >StopIconPtr+2	; Stop Sign icon pointer	pha	lda >StopIconPtr	pha	bra doIconDrawCautionIcon	lda >CautionIconPtr+2 ; Caution Sign icon pointer	pha	lda >CautionIconPtr	phadoIcon	pea 0	; DisplayMode	lda #18	; Horizontal position (LEFT)	pha	lda #8	; Vertical position	(TOP)	pha	ldx #DrawIcon	jsl ToolLocator	lda 1,s	; get return address	sta 7,s	; move to proper location	lda 2,s	;  above input parameters	sta 8,s	pla	; move stack pointer up	pla	;  to new return address location	pla	rtl	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *Error	Proc Export** Description:	This routine will display an alert box identifying the*	error.  NOTE that BadScriptFormat is special cased and*	will also display volume/path name information.  Also,*	VolumeNotFound is not handled here, GS/OS handles it.** Inputs:	A-reg: Contains error code.*	(Expects <ZPTemp to point to current FileSpec field.)** Outputs:	c-flag: set=error was reported, clear=no error** External Refs:	Import CursorArrowOn	Import CursorWatchOn	Import DestMsg	Import DrawStopIcon*	Import Err(nn)	Print Push	Print Off	Import Err27	Import Err28	Import Err2B	Import Err2E	Import Err40	Import Err43	Import Err44	Import Err45	Import Err46	Import Err47	Import Err48	Import Err49	Import Err4A	Import Err4B	Import Err4C	Import Err4D	Import Err4E	Import Err50	Import Err51	Import Err52	Import Err57	Import Err81	Import Err82	Import Err83	Import Err84	Import Err85	Import Err86	Import Err87	Import Err88	Import Err89	Import Err8A	Import Err8B	Import Err8C	Import Err8D	Import Err8E	Import Err8F	Import Err90	Print Pop	Import GetPfxName	Import GetPfxParms	Import InstallRemoveMode	Import Msg	Import OKStr	Import OneSimpleKeyFilter	Import PatchErrorHere	Import SimpleKeyFilter	Import SourceMsg	Import UpdateFlag	Import VNameBuffer	Import VolumeTemplate** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *; Since we are now letting GS/OS handle all the "Ask For Volume" stuff, we; never need to handle a "Volume Not Found" error.	cmp #VolumeNotFound	bne @GoAhead1@IgnoreIt	sec	rtl; There is also another special error condition we can ignore.  When there are; no volumes on line, GS/OS calls that need the volume name will fail because; the Installer nulls them out.  So we can let syntax errors pass on through; if there are no volumes on line.@GoAhead1	cmp #PathSyntax	bne @GoAhead2	tax	; Save the error code	lda >InstallRemoveMode ; Are there any volumes on line	and #bNoVols	; Isolate "no volumes on line" bit	php	; preserve the status flags	txa	; restore the error code	plp	; restore the status flags	bne @IgnoreIt; We've got a real-live, honest-to-goodness error to report!@GoAhead2	phb	; Save callers bank	phk	plb	;  and set to current bank; The error code is in the A-reg and the address of the pathname used when the ; "Volume not Found" error was encountered is in X and Y.	sta Error_Code	stx <NameTemp	; Used only for "AskForVolume"	sty <NameTemp+2	jsr CursorArrowOn	pha	; Save the GrafPort	pha	;  (Don't pull the result.  Leave it on the	ldx #GetPort	;   stack for _SetPort call upon exit.)	jsl ToolLocator; If we have a "Bad Script Format", "Pathname Syntax", or "File Not Found"; error, we want to handle that special by identifying the source and; destination pathnames.	lda Error_Code	cmp #$0086	beq @00	cmp #FileNotFound	beq @00	cmp #PathNotFound	beq @00	cmp #PathSyntax	bne @0@00	jsr DispNames	bra ReportError; If we have a "Volume not Found" error, we want to handle that special with a; dialog asking for the correct volume.@0	cmp #VolumeNotFound	bne ReportError	brl AskForVolume; An error occurred.ReportError	lda Error_Code	; get error code back into a-reg	sep #$0030	; Go into 8 bit A &	X for this	LongA Off	LongI Off	ldy #00	; Try to identify the errorLoop	cmp ErrNums,y	beq KnownErr	; We know it - say something smart	iny	bcs Loop	LongI On	; Back to 16 bit mode	LongA On	rep #$0030; Use a generic message	pha	; Unsigned integer to be converted	pea PatchErrorHere>>16 ; Pointer to output string	pea |PatchErrorHere	pea 0004	; Length of output string	ldx #Int2Hex	jsl ToolLocator	lda Msg	and #$00FF	; Keep only length byte	sta ErrMsgLength	lda #Msg+1	sta ErrMsgPtr	lda #^Msg+1	sta ErrMsgPtr+2	bra ShowDialog; Display a pre-defined error messageKnownErr	LongI On	; Back to 16 bit mode	LongA On	rep #$0030	tya	asl a	asl a	tay	lda ErrPtrs,y	sta <ErrMsgTemp	sta ErrMsgPtr	lda ErrPtrs+2,y	sta <ErrMsgTemp+2	sta ErrMsgPtr+2	lda [<ErrMsgTemp]	; First set up the message length	and #$00FF	sta ErrMsgLength	inc ErrMsgPtr	; Then set up the message pointer	bne ShowDialog	inc ErrMsgPtr+2; Also, display the source and destination pathname info, if appropriate.ShowDialog	stz SourceMsgItemPtr	stz SourceMsgItemPtr+2	lda Error_Code	cmp #$0086	beq @00	cmp #FileNotFound	beq @00	cmp #PathSyntax	bne @000@00	lda >UpdateFlag	; If an update script is NOT currently	bpl @000	;   executing, don't display names!	lda #SourceMsgItem	sta SourceMsgItemPtr	lda #^SourceMsgItem	sta SourceMsgItemPtr+2;;;	lda PathnamesMsg	; Get the LengthByte;;;	and #$00FF	; Mask off first character;;;	sta Pathnames_Length ; Store in template@000	pha	; Space for result	pea StopTemplate>>16 ; Pointer to template	pea |StopTemplate	pea OneSimpleKeyFilter>>16 ; Filter procedure	pea |OneSimpleKeyFilter	ldx #Alert	jsl ToolLocator	pla	; Get the item hit and ignore it.	jsr CursorWatchOn	; Put watch cursor back up.; The "port" upon entry is still on the stack	ldx #SetPort	jsl ToolLocator	lda Error_Code	; restore error code	sec	; keep carry set	plb	rtl	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; Error dialog templatesWidth  equ 500sHeight equ 100sTop      equ (200/2)-(sHeight/2)sLeft     equ (640/2)-(sWidth/2)sBottom   equ sTop+sHeightsRight    equ sLeft+sWidthStopTemplate 	dc.w sTop,sLeft,sBottom,sRight	dc.w 6666	; ID	dc.b $81	dc.b $81	dc.b $81	dc.b $81	dc.l OKButton	dc.l Icon	dc.l ErrorMsgItemSourceMsgItemPtr	dc.l SourceMsgItem	dc.l SourcePathnameItem	dc.l DestMsgItem	dc.l DestPathnameItem;;;	dc.l Pathnames_Msg	dc.l 00000000OKButton	dc.w 0001	; ID	dc.w sHeight-19,sWidth-87  ; Bounds rect for button	dc.w sHeight-8,sWidth-22	dc.w ButtonItem	; Type	dc.l OKStr	; Item descriptor	dc.w 0000	; Item value	dc.w 0001	; Item flag	dc.l 00000000	; Item colorIcon	dc.w 0002		; ItemID	dc.w 8,18,28,76		; ItemRect	dc.w UserItem+ItemDisable	; ItemType	dc.l DrawStopIcon		; ItemDescr	dc.w 0000		; ItemValue	dc.w 0000		; ItemFlag	dc.l 00000000		; ItemColorErrorMsgItem	dc.w 0003	; ID	dc.w 32,18,50,sWidth-16  ; Bounds rect for text	dc.w LongStatText2+ItemDisable ; TypeErrMsgPtr	dc.l Msg	; Item descriptorErrMsgLength	dc.w 0000	; Item value	dc.w 0000	; Item flag	dc.l 00000000	; Item colorSourceMsgItem	dc.w 0004	; ID	dc.w 50,18,60,71	; Bounds rect for text	dc.w StatText+ItemDisable ; Type	dc.l SourceMsg	; Item descriptor	dc.w 0000	; Item value	dc.w 0000	; Item flag	dc.l 00000000	; Item colorSourcePathnameItem	dc.w 0005	; ID	dc.w 50,76,60,sWidth-16  ; Bounds rect for text	dc.w LongStatText+ItemDisable ; TypeSourcePathname	dc.l 00000000	; Item descriptorSourcePathLength	dc.w 0000	; Item value	dc.w 0000	; Item flag	dc.l 00000000	; Item colorDestMsgItem	dc.w 0006	; ID	dc.w 60,18,70,71	; Bounds rect for text	dc.w StatText+ItemDisable ; Type	dc.l DestMsg	; Item descriptor	dc.w 0000	; Item value	dc.w 0000	; Item flag	dc.l 00000000	; Item colorDestPathnameItem	dc.w 0007	; ID	dc.w 60,76,70,sWidth-16  ; Bounds rect for text	dc.w LongStatText+ItemDisable ; TypeDestPathname	dc.l 00000000	; Item descriptorDestPathLength	dc.w 0000	; Item value	dc.w 0000	; Item flag	dc.l 00000000	; Item color;;;;;;Pathnames_Msg	dc.w 3	; ID;;;	dc.w 50,18,70,sWidth-16  ; Bounds rect for text;;;	dc.w LongStatText2+ItemDisable ; Type;;;Pathnames_Pointer dc.l PathnamesMsg+1 ; Item descriptor;;;Pathnames_Length	dc.w 81	; Item value;;;	dc.w 0000	; Item flag;;;	dc.l 00000000	; Item colorError_Code	d