sed to indicate if message should*	        remain until changed (hi-bit on) or be*	        erased on next action (hi-bit clear).** Outputs:	none** External Refs:	Import AlertMsgNo	Import AlertPtrs	Import DialogFlag	Import DialogPort	Import Msg1	Import Msg2	Import Msg3	Import Msg4	Import Msg5	import OldMsgNo** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *; Don't attempt to draw into the Standard Update Dialog!	bit DialogFlag	bpl Begin	brl AlertDoneBegin	pha	; Space for result	pha	ldx #GetPort	; Get current GrafPort	jsl ToolLocator	; leave result on stack for SetPort at end; Same message, or new one?	lda AlertMsgNo	beq SetGrafPort	; branch if no message	cmp OldMsgNo	bne RedrawAlert1	; branch if new message	bra AlertDone1	; done if same message; No message at all: erase old message unless its hi bit is set.; Set grafPort to our'sSetGrafPort	lda DialogPort+2	pha	lda DialogPort	pha	ldx #SetPort	jsl ToolLocator; Check the hi-bit to see if the message should be continuously displayed; until changed.	lda OldMsgNo	bmi AlertDone1; Erase the old message	pea IconRect>>16	pea |IconRect	ldx #EraseRect	jsl ToolLocator	pea Box>>16	pea |Box	ldx #EraseRect	jsl ToolLocator	stz OldMsgNoAlertDone1	bra AlertExit; New message (different from last message); Check to see if we need to print anythingRedrawAlert1	sta OldMsgNo	; AlertMsgNo -> OldMsgNo	pha	; save message number value; First, display the 'talking head' Icon.	pha	; space for result	pha	pea rIcon	pea rIconNoteID>>16	pea |rIconNoteID	ldx #LoadResource	jsl ToolLocator	; handle of resource left on stack	jsl DeReference	; pointer to talking head icon left on stack	pea 0	; DisplayMode	lda IconRect+2	; Horizontal position (LEFT)	pha	lda IconRect	; Vertical position	(TOP)	pha	ldx #DrawIcon	jsl ToolLocator; Set up the correct message pointer and length	pla	; recover message number value	dec a	asl a	; Get the string pointer 