:*	   looking only for installable media (writeable, not boot or install disks, ...).** Inputs:	none* Export NextSameDevice** Description:	This entry point will check the on-line device*	that was previously online, and set controls*	as appropriate for whichever dialog is currently running.*	If not acceptable, it will advance to the next on-line device*	as described above.** Inputs:	none* Export NextThisDevice** Description:	This entry point will advance to the on-line device*	specified by the device number in the accumulator, provided*	that it is a readable/writeable block device, and set controls*	as appropriate for whichever dialog is currently running.*	If not acceptable, it will advance to the next on-line device*	as described above.** Inputs:	A = devnum**** Outputs:	carry set if did not advance to another disk, or if no disks online** External Refs:	Import AlertMsgNo	Import BootVolTest	Import CheckCharacter	Import CheckVolume	Import ConditionBtns	Import CurrentDir	Import CurrentVol	Import CurrentVolBuf	Import CursorArrowOn	Import CursorWatchOn	Import D_Cont_DevNum	Import D_Cont_Parms	Import D_DeviceNum	Import D_Info_Parms	Import DialogFlag	Import Dev_Name	Import DiskNamesTest	Import DispDir2Update	Import DispDisk2Update	Import DispDiskEasy	Import DirSelReq	Import EasyBtnDim	Import EjectControl	Import Eject2Control	Import GetAppDirPtr	Import GetCurDirPtr	Import GStrToGStr	Import InstallRemoveMode	Import ListSize2	Import ListStart2	Import MyPopUpControl	Import MyPopUpCtlHdl	Import NewFolderDim	Import NewList2Call	Import NoVolumesOnLine	Import NumOfSelections	Import OpenControl	Import ResizeAppDirBuf	Import ResizeCurDirBuf	Import SelectWindow	Import SetInstallRemove	Import SetPrefix	Import TargetSetUpComplete	Import UnlockAppDirHdl	Import UnlockCurDirHdl	Import UpdatePopUp	Import VNameBuffer	Import VolumesOnLine	Import WindowSetUpComplete** Exports:	Export GetAccessParms	Export File_Sys_ID	Export Volume_Parms** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	Eject; This entry point must check the volume name in VNameBuffer against; the volume name in CurDirectory and be sure they are the same; before falling through to "NextDevice1", below.	sep #$0030	LongA Off	LongI Off	ldy #00@Loop	iny	cpy CurrentVol	beq @NextDevice1	lda CurrentVol+1,y ; (Skip length byte)	cmp #SeparatorChar	beq @NextDevice1	cmp #'a'	; Convert to UPPERcase if necessary	bcc @StoreTemp	cmp #'z'+1	bcs @StoreTemp	and #%11011111@StoreTemp	sta Temporary	lda VNameBuffer,y	; (No length byte)	cmp #'a'	bcc @Compare	cmp #'z'+1	bcs @Compare	and #%11011111@Compare	cmp Temporary	beq @Loop	LongI On	LongA On	rep #$0030	lda #0000	; Signify: did not advance	sec	rts@NextDevice1	LongI On	LongA On	rep #$0030	Eject; Set a counter which will count down to zero after it has been incremented; twice so we can stop the search if no volumes are on line.NextThisDevice	sta D_DeviceNum	; store device number to D_Info parametersNextSameDevice	lda #0002	sta SearchFlag	bra GetDeviceInfoNextDevice1	Name	; ENTRY POINT & debugging Name for NiftyList	lda #0002	sta SearchFlag; Make a GS/OS D_Info call to the next deviceGetDInfo	inc D_DeviceNumGetDeviceInfo	jsl GSOS	dc.w D_Info	dc.l D_Info_Parms	bcs @1	brl NoError; If we got back an "InvalidDevNum" error, we're out of devices, so ; set the D_Info_DevNum back to 0 and try again.@1	stz D_DeviceNum	dec SearchFlag	bne GetDInfo; We've been through the complete list and then some: no devices to be found!;         If pre-setup: no installable media: point at boot device	jsr NoVolumesOnLine	; Indicate no Volumes on line	lda TargetSetUpComplete	bmi @ItsRunning	stz D_DeviceNum	; make next device number incr to boot volume	bra @OutaHere;         Not during setup: Dim the Install and Remove buttons;          and notify the user there are no volumes on line.@ItsRunning	lda #$008A	; Notify the user	jsl Error	jsr DisableEraseDiskMenu ; disable the Erase Disk menu item	bit DialogFlag	bmi @StandardDialog; The Customized Installation Dialog is running.	lda #Inactive	; Dim the Eject button	jsr EjectControl	lda #Inactive	; Dim the Open button	jsr OpenControl	jsr NewFolderDim	; Dim the New Folder button	lda #Inactive	jsr SelectWindow	jsr NullListAndPopup ; null list, popup	bra @NoVolumesExit;        The Standard Update Dialog is currently running.@StandardDialog	jsr EasyBtnDim	; Dim the "Begin Standard Update" button	lda #Inactive	; Dim the "Eject" button	jsr Eject2Control@NoVolumesExit	jsl GetCurDirPtr	; Dereference & lock <CurDirHdl	jsl GetAppDirPtr	; Dereference & lock <CurDirHdl	ldy #0002	; Clear the volume name	lda #0000	sta [<CurDirPtr],y	sta [<AppDirPtr],y	stz CurrentVol	jsl UnlockCurDirHdl	; Let <CurDirHdl float til needed again	jsl UnlockAppDirHdl	; Let <AppDirHdl float til needed again	bit DialogFlag	bpl @DispCustom	; bra if Custom Install	jsr DispDiskEasy	; Easy Update: invalidate rect	bra @Done@DispCustom	jsr DispDisk2Update	; Custom: Redisplay "Disk to Update:"@Done	lda #$008A	; Report the error to the caller	sec@OutaHere	rts; We got back a legitimate device name.  Get the volume name and update; CurDirectory to show the new volume as the current directory too.; Then update the pop-up menu.NoError	jsl GSOS	dc.w Volume	dc.l Volume_Parms	bcc @GotAVolume@GetDInfo1	brl GetDInfo	; Got an error, try next device;       Check that it is a readable block device@GotAVolume	lda D_Info_Parms+8	; Check the characteristics	and #ReadAllowed+BlockDevice	cmp #ReadAllowed+BlockDevice	bne @GetDInfo1	; Can't install on this, try again;              condition the Eject buttons	lda TargetSetUpComplete ; first time into Easy Update,	beq @noConditioning	;   not conditioning buttons	jsr CheckCharacter	; condition Eject button, Erase menu item (either screen);              If it is NOT writeable, disable INSTALL and REMOVE and notify the user.@noConditioning	lda D_Info_Parms+8	and #WriteAllowed	beq @NotWriteEnabled;              Last thing, check the access privileges.	jsl GSOS	dc.w Get_File_Info	dc.l GetAccessParms;              If not read-enabled, forget it!	lda GetAccessParms+6	and #%0000000000000001 ; Read enabled ?	beq @GetDInfo1	   ; No, try next device;       Activate/deactivate INSTALL and/or REMOVE buttons based on;       whether the volume is write-protected or write-enabled.	jsl CheckVolume	; check CurrentVol	bmi @NotWriteEnabled ; If write-protected, dim control	bvc @ProDOSVol	; ProDOS writeable media always ok to continue;             non-ProDOS volume: not installable by Easy Update	lda TargetSetUpComplete ; first time into Easy Update, looking for	beq @GetDInfo1	;   installable media only; look at next device;             ProDOS or non-ProDOS volume: continue@ProDOSVol	lda GetAccessParms+6	and #%0000000000000010 ; Isolate write bit	bne @WriteEnabled;              The volume is NOT write-enabled!  Deactivate INSTALL and REMOVE;              and notify the user that the disk is not writeable.@NotWriteEnabled	lda TargetSetUpComplete ; first time into Easy Update, looking for@beqGetDInfo1	beq @GetDInfo1	;   installable media only	lda InstallRemoveMode	ora #bWriteProtect	; force WriteProtect flag to 1	sta InstallRemoveMode	bit DialogFlag	bmi @StandardDialog1	jsr SetInstallRemove ; custom install	lda #$0004	bra @1;             Standard Install@StandardDialog1	jsr EasyBtnDim	bra @2;              The volume is write enabled!  Activate INSTALL and REMOVE.@WriteEnabled	lda InstallRemoveMode	and #bWriteProtect--$FFFF ; clear WriteProtect bit	sta InstallRemoveMode	bit DialogFlag	bmi @StandardDialog2	jsr SetInstallRemove ; custom install: condition Install & Remove btns	lda AlertMsgNo	cmp #AlertMsg3	; 'Folder Selection window is above'	beq @2	cmp #AlertMsg6	; ÔCanÕt install to active Boot diskÕ	beq @2	lda #AlertNoMsg	; No alert message needed	bit WindowSetupComplete ; Don't draw into window if setup	bpl @2	;       is not complete.@1	sta AlertMsgNo	jsr AlertMsg	bra @2;             Standard Install@StandardDialog2	lda TargetSetUpComplete ; first time into Easy Update, looking for	bne @DoCondition	;   installable media only; don't condition btns	jsr BootVolTest	; is target the Boot volume?	beq @beqGetDInfo1	; bra if target is Boot volume: not installable		jsr DiskNamesTest	; is target one of the Installer disks (listed in rDiskNames)?	beq @beqGetDInfo1	; bra if target is an Installer disk: not installable	lda D_Info_Parms+20	; Check device identification	beq @beqGetDInfo1	; ID = zero = DISK ][ (5.25) : not installable	jsr SetCurrentVol	bra NextDone@DoCondition	jsr ConditionBtns	; write enabled: check volumes for BootPrevent, ...;       Make "everything" = CurrentVol   (NOTE: CurrentDir must be PStr)@2	jsr SetCurrentVol; Activate the PopUp control, if appropriate.	bit DialogFlag	; Don't do anything if Standard Update	bmi DispEasyDisk	;   is currently running.	lda NumOfSelections	; Don't activate if no scripts selected	beq NextDeviceExit;rdl: moved 10/16 to NextDone:	jsr VolumesOnLine	; There ARE volumes on line; Activate the popup menu control	bit DirSelReq	bpl NextDeviceExit	lda #Active	jsr MyPopUpControl; Pass the Device_ID to the PopUp menu custom control so it can display; the proper icon and update the pop-up menuNextDeviceExit	lda WindowSetupComplete ; DON'T fiddle with a control	beq NextDone	; that isn't ready for fiddling!!!	pea 0000	; (CtlRefCon is a LongWord)	lda D_Info_Parms+20	; (Device_ID)	pha	lda MyPopUpCtlHdl+2	pha	lda MyPopUpCtlHdl	pha	ldx #SetCtlRefCon	jsl ToolLocator	jsr UpdatePopUp; Display the proper message at the top of the screen	bit DialogFlag	bpl DispCustom	; bra if Custom InstallDispEasyDisk	jsr DispDiskEasy	; Easy Update: invalidate rect	bra NextDoneDispCustom	bit DirSelReq	; Are we displaying	directory or volume?	bmi DispDir	jsr DispDisk2Update	bra NextDoneDispDir	jsr DispDir2Update; Set the prefix to CurDirectoryNextDone	jsr SetPrefix	jsr VolumesOnLine	; There ARE volumes on line	rts	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * ** Description:	Disable/Enable the Erase Disk menu item* Inputs:		Import EraseDiskState** Outputs:	None	Export DisableEraseDiskMenu	Export DoEraseDiskMenu	Export EnableEraseDiskMenu* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *DisableEraseDiskMenu ldx #DisableMItem	bra DoEraseDiskMenuEnableEraseDiskMenu	ldx #EnableMItemDoEraseDiskMenu	stx EraseDiskState	pea EraseDiskItemID	jsl ToolLocator	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; Customized Installation: no disk online: null list, popupNullListAndPopup	stz ListSize2	; Deactivate the 2nd list window	stz ListStart2	; (temporarily zero this out)	jsr NewList2Call	inc ListStart2	; (put it back to "1");	lda #Inactive;	jsr SelectWindow	jsl GetCurDirPtr	; Dereference & lock <CurDirHdl	lda #0000	ldy #0002	sta [<CurDirPtr],y	; Null out directory name	jsl ResizeCurDirBuf	; Resize the memory	stz CurrentVol	; Null out volume name	jsl UnlockCurDirHdl	; Let <CurDirHdl float til needed again	pea 0000	; hi-word (CtlRefCon is a LongWord)	lda #0032	; A non-existant device number to;;; rdl: redundant?	sta D_Info_Parms+20	pha	;   force a null icon.	lda MyPopUpCtlHdl+2	pha	lda MyPopUpCtlHdl	pha	ldx #SetCtlRefCon	jsl ToolLocator	jsr UpdatePopup	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; Make "everything" = CurrentVol   (NOTE: CurrentDir must be PStr)SetCurrentVol		sep #$0020	LongA Off	ldy CurrentVol	beq LoopDone	; If length byte = zero, done	iny	; Increment the length word and...	sty CurrentVol		lda #SeparatorChar	;   add a trailing separator char	iny	sta CurrentVol,yLoop	lda CurrentVol,y	sta CurrentDir-1,y	; (Vol names will always fit display)	dey	bne LoopLoopDone	lda CurrentVol	sta CurrentDir	; Store lengthByte here (a PStr)	LongA On	rep #$0020	jsl GetAppDirPtr@TryAgain1	pea CurrentVolBuf>>16	pea |CurrentVolBuf	pei <AppDirPtr+2	pei <AppDirPtr	jsl GStrToGStr	jsl ResizeAppDirBuf	bcs @TryAgain1	jsl UnLockAppDirHdl	jsl GetCurDirPtr	; Dereference & lock <CurDirHdl@TryAgain	pea CurrentVolBuf>>16 ; Handle storage at <CurDirPtr	pea |CurrentVolBuf	;   separately using GStr tools	pei <CurDirPtr+2	pei <CurDirPtr	jsl GStrToGStr	jsl ResizeCurDirBuf	; Resize buffer to fit	bcs @TryAgain	; Try again if we didn't get it all	jsl UnlockCurDirHdl	; Let CurDir float again	lda CurrentVol	; get length	beq @GoOn	dec CurrentVol	; remove trailing separator char@GoOn	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .Volume_Parms	dc.w 5	; Parameter countDev_Name_Ptr	dc.l Dev_Name+2	; Device name pointerVol_Name_Ptr	dc.l CurrentVolBuf	; Volume name pointer	ds.l 1	; Total blocks (not used)Free_Blocks	ds.l 1	; Free blocksFile_Sys_ID	ds.w 1	; File system identificationGetAccessParms	dc.w 0002	; Parameter count	dc.l CurrentVol	; Volume name pointer	dc.w 0000	; AccessSearchFlag	ds.b 2Temporary	ds.b 1		EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *BuildDirName	ProcName Export** Description:	BuildDirName is a subroutine to build a shortened version*	of the full pathname.  The full pathname is expected to be*	at '<CurDirPtr' and the shortened version for display will*	be in "CurrentDir.  The shortened display will be of the*	form:**	: <volume_name> :...: <dir_name> : <dir_name> : <dir_name> :** NOTE:	This routine is called from a subroutine that DOES NOT use*	the Installer's d-page.  It has set d-page to be its stack!*	<CurDirPtr is NOT accessible until we reset dPage reg.** Inputs:	None (<CurDirPtr expected to point to a "GStr" which is a*	      full pathname.)** Outputs:	None (CurrentDir will contain a Pascal string for display)** External Refs:	Import CurrentDir	Import Dir2Rect	Import Dir2Width	Import GetCurDirPtr	Import GStrToPStr	Import MyZP	Import UnlockCurDirHdl** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	phd	; Save caller's d-page	lda MyZP	;  and set Installer's d-page	tcd; First, simply check to see if the full name will fit in the available space.	sec	; Calculate the available space	lda #Right-30	;  (right side of dialog box with margin)	sbc Dir2Rect+2	;  (- beginning of Dir2Update string	)	sbc Dir2Width	;  (- width of Dir2Update string	)	sta MaxWidth	jsl GetCurDirPtr;       CurDirPtr points to a GStr!  The StringWidth tool ONLY knows about;       Pascal strings!  If the length is greater than 255 bytes, we know;       it isn't going to fit.	ldy #0002	lda [<CurDirPtr],y	cmp #255	bcs NoFit;       It's less than 255 characters, so...  Temporarily convert the GStr;       to a PStr for the tool call, then convert it back to a GStr for;       everything that follows.	xba	; Form a length byte from the length	sta [<CurDirPtr],y	;  word	clc	; Set up a pointer to point to the	lda <CurDirPtr	;  length byte	adc #0003	sta <ZPTemp	lda <CurDirPtr+2	adc #0000	sta <ZPTemp+2	pha	; Room for result	pei <ZPTemp+2	; String pointer	pei <ZPTemp	ldx #StringWidth	jsl ToolLocator	plx	stx StringWidth1	; String length	ldy #0002	; Restore the length word	lda [<CurDirPtr],y	xba	sta [<CurDirPtr],y	cpx MaxWidth	; FINALLY!  Will it fit?	bcs NoFit; The full name will fit in the space, so simply move it to	CurrentDir.	pei <CurDirPtr+2	; Source pointer	pei <CurDirPtr	pea CurrentDir>>16	; Destination pointer	pea |CurrentDir	jsl GStrToPStr	brl Finished	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; The full pathname	won't fit.  So, begin by finding the second; SeparatorCharNoFit	sep #$0030	LongA Off	LongI Off	ldy #GStrOverhead+1	; Skip first SeparatorChar & next charScanLoop	iny	lda [<CurDirPtr],y	; Look for next SeparatorChar	sta CurrentDir-3,y	; (CurrentDir is a PStr)	cmp #SeparatorChar	bne ScanLoop; We've got ': <volume_name> :'.  Now store a space, three periods, a space,; and a SeparatorChar	iny	lda #' '	sta CurrentDir-3,y	lda #'.'	iny	sta CurrentDir-3,y	iny	sta CurrentDir-3,y	iny	sta CurrentDir-3,y	iny	lda #' '	sta CurrentDir-3,y	iny	lda #SeparatorChar	sta CurrentDir-3,y	dey	; Deduct (GStrOverhead -1) because	dey	;  CurrentDir is a PStr	dey	sty CurrentDir	; Store interim length	LongA On	LongI On	rep #$0030; We've got ': <volume_name> : ... :'.  Now find out how wide the string is and; how much room we have left for the remainder of the string.	pha	; Space for result	pea CurrentDir>>16	; String pointer	pea |CurrentDir	ldx #StringWidth	jsl ToolLocator	pla	sta StringWidth1 ; Length of 'front end' string	sec	lda MaxWidth	sbc StringWidth1	sta StringWidth2; Now start at end of string, picking up a name at a time and checking to see; if it will fit in	the remaining space, until we have the largest string that; will fit.	stz FirstPassFlag	stz String2Length	; Zero the character counter	ldy #0002	; Get the length word	lda [<CurDirPtr],y	inc a	; Add on GStr overhead	inc a	inc a	inc a	tay	sep #$0020	LongA Off	dey	; #####BuildLoop	dey	inc String2Length	lda [<CurDirPtr],y	cmp #SeparatorChar	bne BuildLoop	sty String2Pos	; Store index into string	LongA On	rep #$0020	pha	; Room for result	clc	lda <CurDirPtr	adc String2Pos	tax	lda <CurDirPtr+2	adc #0	pha	; Push text pointer	phx	lda String2Length	; Push text length	pha	ldx #TextWidth	jsl ToolLocator	pla	cmp StringWidth2	bcs TooLong	ldy String2Pos	; Store the old values before trying again	sty OldPos	lda String2Length	sta OldLength	sec	; Indicate we've completed the 1st pass	ror FirstPassFlag	sep #$0020	LongA Off	bra BuildLoop; The last try was too long.  If this was the first pass through the remainder; of the name, we've got a problem.	LongA OnTooLong	bit FirstPassFlag	; Is this the first pass?	bmi BackUpOne; Oh Oh!  We've got a real problem!  The volume name plus the folder name; produces a name that is still too long!  So...  We can only display the; folder name with three periods preceeding it.	sep #$0020	LongA Off	ldy String2Pos	ldx #0001	lda #'.'	sta CurrentDir,x	inx	sta CurrentDir,x	inx	sta CurrentDir,x	inx	lda #' '	sta CurrentDir,x	inx	lda #SeparatorChar	sta CurrentDir,xFilenameLoop	inx	iny	lda [<CurDirPtr],y	sta CurrentDir,x	cmp #SeparatorChar	bne FilenameLoop	txa	; transfer count to 8-bit register	sta CurrentDir	; p-string: 8-bit count	bra FinalExit; We've already backed up more than one level, so back up to the previous; SeparatorCharBackUpOne	LongA On	ldy #02	lda [<CurDirPtr],y	inc a	inc a	sta <ZPTemp	lda #0000	; clear hi accum	sep #$0020	LongA Off	lda CurrentDir	; get byte count of folder name already there	tax	; transfer 0/byteCount -> X	ldy OldPosFinalLoop	inx	iny	lda [<CurDirPtr],y	sta CurrentDir,x	cpy <ZPTemp	bne FinalLoop	txa	; move count to 8-bit register	sta CurrentDir	; p-string: 8-bit countFinalExit	LongA On	rep #$0020;Finished	pld	; Restore caller's d-page	rts;FirstPassFlag	ds.b 2MaxWidth	ds.b 2StringWidth1	ds.b 2StringWidth2	ds.b 2String2Pos	ds.b 2String2Length	ds.b 2OldPos	ds.b 2OldLength	ds.b 2	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *InitPrefix	Proc Export** Description:	Clears prefix zero and falls through to "SetPrefix".* Export SetPrefix** Description:	Sets the system prefix (prefix eight) to contents of*	<CurDirPtr.* Export SetPrefixCurrVol** Description:	Sets the system prefix (prefix eight) to contents of*	CurrentVol.** Inputs:	none** Outputs:	none** External Refs:	Import CurrentVol	Import GetCurDirPtr	Import UnlockCurDirHdl** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	lda #0001	; Null out prefix 1 so that GS/OS will	sta PrefixNumber	;  use prefix 8 as the system prefix.		; (Prefix 8 permits unlimited length.)	lda #NullString	sta PrefixPath	lda #^NullString	sta PrefixPath+2	jsl GSOS	dc.w Set_Prefix	dc.l PrefixParms	lda #0008	sta PrefixNumberSetPrefix	jsl GetCurDirPtr	clc	lda <CurDirPtr	adc #0002	sta PrefixPath	lda <CurDirPtr+2	adc #0000	sta PrefixPath+2	jsl GSOS	dc.w Set_Prefix	dc.l PrefixParms	jsl UnlockCurDirHdl	rtsSetPrefixCurrVol	lda #CurrentVol	sta PrefixPath	lda #CurrentVol>>16	sta PrefixPath+2	jsl GSOS	dc.w Set_Prefix	dc.l PrefixParms	rtsPrefixParms	dc.w 0002	; pCountPrefixNumber	ds.w 1	; Prefix numberPrefixPath	ds.l 1	; Prefix pathnameNullString	dc.w 0000	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *InitVolume	Proc Export** Description:	Initializes the Volume_Parms table so we will have*	valid data there upon startup.** Inputs:	none** Outputs:	none** External Ref:	Import D_DeviceNum	Import D_Info_Parms	Import OpenTarget	Import Volume_Parms** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	lda #0001	; 1st device is always boot device	sta D_DeviceNum	jsl GSOS	dc.w D_Info	dc.l D_Info_Parms	bcs Exit	jsl GSOS	dc.w Volume	dc.l Volume_Parms	bcs Exit; Open Target volume's directory to protect against duplicate-named disks	jsr OpenTargetExit	rts	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *UpdatePopUp	ProcName Export** Description:	Updating is accomplished using InsertPathMItems, resulting in*	the GString at <CurDirPtr becoming the last entry in the*	PopUp menu with the volume name as item number one at the*	bottom of the menu (each successive level progressing up the*	menu).**	NOTE:  If directory selection is NOT required, this routine*	simply deletes all entries in the PopUp menu so that it*	will not display any entry while inactive.** Inputs:	none** Outputs:	none** External Refs:	Import DirSelReq	Import GetCurDirPtr	Import MyPopUpCtlHdl	Import QuitFlag	Import UnlockCurDirHdl** Entry Points:	Export MenuItemID** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *; Make the PopUp the current menu bar@DoUpdate	pha	; Get the current menu bar	pha	ldx #GetMenuBar	jsl ToolLocator	;   and leave it on the stack	lda MyPopUpCtlHdl+2	; Set PopUp as current menu bar	pha	lda MyPopUpCtlHdl	pha	ldx #SetMenuBar	jsl ToolLocator	lda MenuItemID	beq ReleaseMemory	Eject; Clear all entries from the PopUp menu releasing the memory.DeleteLoop	lda MenuItemID	pha	ldx #DeleteMItem	jsl ToolLocator	dec MenuItemID	bne DeleteLoop;     delete the handles in InsertPathMItems' structure.	lda InsertHandle1+2	pha	lda InsertHandle1	pha	ldx #DisposeHandle	jsl ToolLocator	lda InsertHandle2+2	pha	lda InsertHandle2	pha	ldx #DisposeHandle	jsl ToolLocator	stz InsertHandle1	; zero out handles to protect system	stz InsertHandle2	stz InsertHandle1+2	stz InsertHandle2+2; If directory selection is NOT required, there is no need to build up a new; PopUp menu.  So, skip to the exit.ReleaseMemory	bit DirSelReq	bpl Exit; get the current directory, and set the popup menu to it.CreateCopy	jsl GetCurDirPtr	; gets & locks Current Directory;     popup flags: device @ bottom (0); (0); open folders icons (1); use routine (0);;        fully expanded pathPtr (1)	lda #$0014	; flags	pha	clc	; Point to the strings lengthWord	lda <CurDirPtr	adc #0002	tax	lda <CurDirPtr+2	adc #0000	pha	phx	pea 0	; device number (using routine to get it)	pea PopUpMenuID	; menuID: the menu to insert into (popup)	pea 0	; afterID: insert at end of list	pea 1	; startingID: start numbering items with #1	pea InsertResults>>16	pea |InsertResults	ldx #InsertPathMItems	jsl ToolLocator	jsl UnlockCurDirHdl	lda MenuItemID	; This is the way to get the Menu Mgr	pha	;   to draw the proper item into the	lda MyPopUpCtlHdl+2	;   the PopUp control.	pha	lda MyPopUpCtlHdl	pha	ldx #SetCtlValue	jsl ToolLocatorExit	ldx #SetMenuBar	; Restore the previous current menu	jsl ToolLocator	;   bar from handle left on stack	rtsInsertResultsMenuItemID	dc.w $0000	   ; itemIDInsertHandle1	ds.l 1InsertHandle2	ds.l 1	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *SimpleKeyFilter	ProcName Export*	export OneSimpleKeyFilter** Description:	SimpleKeyFilter *	traps <Return> and maps it as a hit on ID #1, and *	traps <Escape> and cmd-. and maps it as a hit on ID #2.*	NOTE: This proc only called by dialog manager.** Description:	OneSimpleKeyFilter *	traps <Return> and maps it as a hit on ID #1, and *	traps <Escape> and cmd-. and maps it as a hit on ID #1.*	NOTE: This proc only called by dialog manager.** Inputs:	Word space for result*	Longword pointer to dialog's grafPort*	Longword pointer to the event*	Longword pointer to the item hit** Outputs:	Boolean word: TRUE = ignore** External Refs:	none** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *Result	equ 20	; 2-byte boolean (TRUE=ignore)TheDialogPtr	equ 16	; 4-byte pointer to the dialog's GrafPortEventPtr	equ 12	; 4-byte pointer to the eventItemHitPtr	equ  8	; 4-byte pointer to the item hitReturnAddress	equ  5	; 3-byte return addressEscapeDoes	equ  3	; 2-byte mapping of Esc key to OK or Cancel; D-Reg storage	equ  1	; 2-byte D-reg storage	lda #0002	; two-button dialog: map Esc to Cancel button	bra mapEscape; filter for one-button dialogs to allow Escape in addition to Return to get rid of dialogOneSimpleKeyFilter	lda #0001	; one-button dialog: map Esc to OK buttonmapEscape	pha	; push mapping of Esc key onto the stack; Set up stack as our direct page	phd	tsc	tcd; Check for key down events.  Everything else, we'll just pass on for; processing.	lda [EventPtr]	cmp #KeyDownEvent	bne @NotHandledHere; We got a KeyDown event.  First get the key.; Then look at the key modifiers.  If certain; modifier keys were pressed, we want to ignore the key.	ldy #Message	lda [<EventPtr],y	; get the key	tax	; save in X	ldy #Modifiers	lda [<EventPtr],y	; get the modifiers	and #ControlKey+OptionKey+AppleKey	beq @RegChar	and #AppleKey	beq @NotHandledHere	; not handled if control or option key; got AppleKey down: If it is Apple-. , indicate a hit on the "Cancel" button	cpx #'.'	beq @Cancel	; same as Escape key	bra @NotHandledHere	; no other Command-keys handled; Look at a nonmodified key;   If it is the <Escape> character, indicate a hit on the "Cancel" button;   If it is the <Return> character, indicate a hit on the "OK" button@RegChar	cpx #Return	beq @OK	cpx #Escape	bne @NotHandledHere; Escape key or Cmd-. hit@Cancel	lda <EscapeDoes	; ID of item to pass back: 	bra @StoreValues	;   mapped to  Cancel (if one-button, mapped to OK)@OK	lda #0001	; ID of item to hit@StoreValues	sta [ItemHitPtr]	; indicate to calling routine which item was hit; Get handle of button corresponding to ID in accum	pha	; Room for result	pha	pei TheDialogPtr+2	; Dialog's GrafPort	pei TheDialogPtr	pha	; Item for which handle is desired	ldx #GetControlDItem	jsl ToolLocator	plx	; Item's handle	ply; Now blink the button	pea #0000	; push parameters for second HiliteControl	phy	; ItemÕs handle	phx	pea SimpleButton	; push parameters for first	phy	phx	ldx #HiliteControl	jsl ToolLocator	ldx #HiliteControl	; parameters previously pushed	jsl ToolLocator; The calling routine should ignore the key down event (handled here).@HandledHere	lda #$FFFF	bra @StoreResult; The calling routine should process the key down event (not handled here).@NotHandledHere	lda #$0000@StoreResult	sta Result; Restore callers environment.	lda ReturnAddress	sta Result-3	lda ReturnAddress+1	sta Result-2	pld	tsc	clc	adc #0014	tcs	lda #0000	clc	rtl	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *HelpControl	Proc Export** Description:	Activates or deactivates the Help control.** Inputs:	A-reg = #Active: Control will be activated*	A-reg = #Inactive: Control will be deactivated** Outputs:*	none** External Refs:	Import HelpCtlHdl** Entry Points:*	none** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	pha	; Push active/inactive flag	lda HelpCtlHdl+2	pha	lda HelpCtlHdl	pha	ldx #HiliteControl	jsl ToolLocator	rts	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *BootVolTest	ProcName Export** Description:	Installing to Boot volume?* 	Compares VolStr (boot volume) with CurrentVol (current volume).** Inputs:	none** Outputs:	beq: they're the same (installing to Boot volume).*	bne: they're not the same (not installing to Boot volume).** External Refs:	Import VolStr	Import CurrentVol** Entry Points:*	none** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	lda CurrentVol	; get current volumename len	cmp VolStr	beq CompareStr	tax	; save index to get last char	dec a	; see if there's a separator at end of CurrentVol	cmp VolStr	bne BootEnd	; bra if they're not the same: no match	tay	; save VolStr's len	lda CurrentVol,x	and #$FF00	; just last char	cmp #SeparatorChar*$100	bne BootEnd	; bra if there's not a separator at end: no match	tya	; retrieve VolStr's lenCompareStr	taxBootLoop	lda VolStr,x	; 2 bytes, so don't have to inx to get past len	cmp CurrentVol,x	bne BootEnd	dex	cpx #1	bne BootLoopBootEnd	rts	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *DiskNamesTest	ProcName Export** Description:	Installing to one of the Installer disks (listed in rDiskNames)?* 	Compares rDiskNames (DiskNamesHdl) with CurrentVol (current volume).** Inputs:	none** Outputs:	beq: they're the same (installing to Boot volume).*	bne: they're not the same (not installing to Boot volume).** External Refs:	Import CurrentVol	Import NoCaseCompare8bit	Import StandardNo** Entry Points:*	none** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	lda StandardNo	; rDiskNames found and loaded?	bne NamesEnd	; bra if not found -- they're not the same	ldx <DiskNamesHdl+2	lda <DiskNamesHdl	jsl DeRef	sta <DiskNamesPtr	stx <DiskNamesPtr+2	lda [<DiskNamesPtr]	; # of disknames in resource	dec a	; 0-base #	sta temp	inc <DiskNamesPtr	; point to first string	inc <DiskNamesPtr; loop through all disknamesNamesLoop	lda [<DiskNamesPtr]	; length of this diskname	cmp CurrentVol	beq DoCompare	inc a	; see if there's a separator at end of CurrentVol	cmp CurrentVol	bne NameEnd	; bra if not the same len; do next diskname	tax	lda CurrentVol,x	and #$FF00	; just last char	cmp #SeparatorChar*$100	bne NameEnd	; bra if there's not a separator at end: no match	lda [<DiskNamesPtr]	; get len of this diskname againDoCompare	inc a	; incr to index last char	tay	; save index in X, Y	tax; loop through this diskname	sep #$0020	LongA OffNameLoop	lda  [<DiskNamesPtr],y ; get char	xba	lda CurrentVol,x	; get other char	jsl NoCaseCompare8bit ; compare, not case-sensitive	bne NameEnd16	dex	dey	cpy #1	; done? (with chars 2 thru len+1)	bne NameLoop	LongA On	rep #$0020	bra NamesEndUnlock	; every character matched!: return beq in z flag; advance to next disknameNameEnd16	LongA On	rep #$0020NameEnd	lda [<DiskNamesPtr]	; length of diskname we just finished with	inc a	; incr to len of diskname + length word	inc a	clc	adc <DiskNamesPtr	sta <DiskNamesPtr	bcc noBankIncr	; branch if no carry into bank byte	inc <DiskNamesPtr+2noBankIncr	dec temp	bpl NamesLoop	; 0-based: bra if not thru all disknames		;   else no matches: z flag clear ($FFFF=bne)NamesEndUnlock	php	; save z flag	pei <DiskNamesHdl+2	; Unlock the handle	pei <DiskNamesHdl	ldx #HUnlock	jsl ToolLocator		plp	; retrieve z flagNamesEnd	rtstemp	ds.w 1	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *SetInstallRemove	ProcName Export** Description:	Customized Dialog:*	SetInstallRemove Activates the Install and Remove controls*	only if InstallRemoveMode flags are properly set.** Inputs:	none** Outputs:	none** External Refs:	Import AlertMsgNo	Import DirSelReq	Import InstallCtlHdl	Import InstallRemoveMode	Import NewFolderActive	Import NewFolderDim	Import RemoveCtlHdl	Import WindowSetupComplete	Export InstallControlOn	Export InstallControlOff** NOTE: see Installer.Equates for InstallRemoveMode bit assignments** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *; if PreventBoot flag set & VolStr (boot volume) = CurrentVol (current volume);      turn off Install & Remove buttons 	lda InstallRemoveMode ; Activate INSTALL if appropriate	and #bPreventBoot	beq TestBits	  ; bra if PreventBoot not set;      PreventBoot flag set: test for VolStr = CurrentVol	jsr BootVolTest	bne TestBits	; not installing to Boot volume;      Boot Disk: Prevent Install/Remove: put Talking Head message, then dim buttons	lda #AlertMsg6	sta AlertMsgNo	bit WindowSetupComplete ; Don't draw it til set up complete	bpl @SkipAlertMsg	jsr AlertMsg@SkipAlertMsg	bra InstallRemoveOffTestBits	lda AlertMsgNo	cmp #AlertMsg6	bne @TestBits1	lda #AlertNoMsg	; if ÒBoot DiskÓ message was up, remove it	sta AlertMsgNo; activate New Folder if appropriate@TestBits1	lda InstallRemoveMode ; Activate INSTALL if appropriate	and #bWriteProtect	bne NewFolderOff	  ; bra if set, should be inactive	bit DirSelReq	bpl NewFolderOff	; hi-bit set=directory name required	jsr NewFolderActive	; make New Folder button active	bra SetInstallNewFolderOff	jsr NewFolderDim	; dim New Folder button; activate Install if appropriateSetInstall	lda InstallRemoveMode ; Activate INSTALL if appropriate	and #bWriteProtect|bNoVols|bNoScripts	bne InstallOff	  ; anything set, should be inactive	jsr InstallControlOn  ; everything clear, should be active	bra SetRemoveInstallOff	jsr InstallControlOff; and activate Remove if appropriateSetRemove	lda InstallRemoveMode ; Activate REMOVE if appropriate	and #bWriteProtect|bNoVols|bNoScripts|bNoRemove	bne RemoveOff	  ; anything set, should be inactive	jsr RemoveControlOn  ; everything clear, should be active	bra SetDoneRemoveOff	jsr RemoveControlOffSetDone	rts; deactivate the INSTALL and REMOVE controlsInstallRemoveOff	jsr InstallControlOff	jsr RemoveControlOff	rts; Turn the INSTALL control on.InstallControlOn	ldx #Active	bra InstallControl; Turn the INSTALL control off.InstallControlOff	ldx #InactiveInstallControl	phx	; Push active/inactive flag	lda InstallCtlHdl+2	pha	lda InstallCtlHdl	pha	ldx #HiliteControl	jsl ToolLocator	rts; Turn the REMOVE control on provided Remove "should" not be inactive.RemoveControlOn	ldx #Active	bra RemoveControl; Turn the REMOVE control off.RemoveControlOff	ldx #InactiveRemoveControl	phx	; Push active/inactive flag	lda RemoveCtlHdl+2	pha	lda RemoveCtlHdl	pha	ldx #HiliteControl	jsl ToolLocator	rts	EndP ;{SetInstallRemove}	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *DiskControl	Proc Export** Description:	Activates or deactivates the Disk control.** Inputs:	A-reg = #Active: Control will be activated*	A-reg = #Inactive: Control will be deactivated** Outputs:*	none** External Refs:	Import DiskCtlHdl** Entry Points:*	none** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	pha	; Push active/inactive flag	lda DiskCtlHdl+2	pha	lda DiskCtlHdl	pha	ldx #HiliteControl	jsl ToolLocator	rts	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *OpenControl	Proc Export** Description:	Activates or deactivates the Open control.** Inputs:	A-reg = #Active: Control will be activated*	A-reg = #Inactive: Control will be deactivated** Outputs:*	none** External Refs:	Import OpenCtlHdl** Entry Points:*	none** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	pha	; Push active/inactive flag	lda OpenCtlHdl+2	pha	lda OpenCtlHdl	pha	ldx #HiliteControl	jsl ToolLocator	rts	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *EjectControl	Proc Export** Description:	Activates or deactivates the Eject control.** Inputs:	A-reg = #Active: Control will be activated*	A-reg = #Inactive: Control will be deactivated** Outputs:*	none** External Refs:	Import EjectCtlHdl** Entry Points:*	none** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	pha	; Push active/inactive flag	lda EjectCtlHdl+2	pha	lda EjectCtlHdl	pha	ldx #HiliteControl	jsl ToolLocator	rts	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *NewFolderActive	Proc Export** Description:	Activates or deactivates the New Folder control.** Inputs:	A-reg = #Active: Control will be activated*	A-reg = #Inactive: Control will be deactivated** Outputs:*	none** External Refs:	Import NewFolderCtlHdl** Entry Points:	Export NewFolderDim** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	lda #Active	bra NewFolderControlNewFolderDim	lda #InactiveNewFolderControl	pha	; Push active/inactive flag	lda NewFolderCtlHdl+2	pha	lda NewFolderCtlHdl	pha	ldx #HiliteControl	jsl ToolLocator	rts	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *SelectWindow	Proc Export** Description:	Folder List:*	Activates or deactivates the application folder selection*	window, its scroll bar, and the popup menu above it.** Inputs:	A-reg = #Active: window and scroll bar will be activated*	A-reg = #Inactive: window and scroll bar will be deactivated** Outputs:	none** External Refs:	Import ListSize2	Import MenuItemID	Import MyPopUpCtlHdl	Import NewList2Call	Import SelectListBarHdl	Import SelectListCtlHdl	import WindowSetUpComplete* Entry Points:	Export MyPopUpControl** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	pha	; Push active/inactive flag for 4th action	pha	; Push active/inactive flag for 3rd action	pha	; Push active/inactive flag for 2nd action	pha	; Push active/inactive flag for 1st action	bne NullList; If we activating, create a new list,	jsr NewList2Call	bra SkipNullList; If we deactivating, create a null list.NullList	lda ListSize2	; Preserve the old ListSize	pha	stz ListSize2	jsr NewList2Call	pla	sta ListSize2;;;	pea PrintListMem>>16 ;drawPtr     (member drawing routine);;;	pea |PrintListMem;;;	pea 0000	; listStart   (item number);;;	lda AppFolderListHdl+2	; listRef     (handle);;;	pha;;;	lda AppFolderListHdl;;;	pha;;;	pea 0001	; listRefDesc (listRef is a handle);;;	pea 0000	; listSize;;;	lda SelectListCtlHdl+2 ; ctlHandle;;;	pha;;;	lda SelectListCtlHdl;;;	pha;;;	ldx #NewList2;;;	jsl ToolLocatorSkipNullList; Now go ahead and activate/deactivate the controls as required.		; Active/inactive flag already on stack	lda SelectListCtlHdl+2	pha	lda SelectListCtlHdl	pha	ldx #HiliteControl	jsl ToolLocator		; Active/inactive flag already on stack	lda SelectListBarHdl+2	pha	lda SelectListBarHdl	pha	ldx #HiliteControl	jsl ToolLocator	pla	; If were activating, mark rect "valid"	bne SkipValidRect	;  but ONLY If window setup is complete!	bit WindowSetUpComplete	bpl SkipValidRect	pea RectPointer>>16	pea |RectPointer	ldx #ValidRect	jsl ToolLocatorSkipValidRect		; Active/inactive flag already on stack	pla	; get last of them; Active/inactive flag is in accumMyPopUpControl	ldx MyPopUpCtlHdl+2	phx	ldx MyPopUpCtlHdl	phx	tax	; check flag	beq @activate	ldx #HideControl	bra @doit@activate	ldx #ShowControl@doit	jsl ToolLocator	rtsRectPointer	dc.w Height-117,AppWindowLeft,Height-45,Width-29	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *EasyBtnDim	Proc Export** Description:	Activates or deactivates the "Begin Easy Update" control*	in the Easy Update dialog window.** Outputs:	none** External Refs:	Import StandardCtlHdl	Export EasyBtnActive** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	lda #Inactive	bra BeginStdControlEasyBtnActive	lda #ActiveBeginStdControl	pha	lda StandardCtlHdl+2	pha	lda StandardCtlHdl	pha	ldx #HiliteControl	jsl ToolLocator	rts	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *Eject2Control	Proc Export** Description:	Activates or deactivates the "Eject" control in the*	in the Easy Update dialog window.** Inputs:	A-reg = #Active: window and scroll bar will be activated*	A-reg = #Inactive: window and scroll bar will be deactivated** Outputs:	none** External Refs:	Import Eject2CtlHdl** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	pha	lda Eject2CtlHdl+2	pha	lda Eject2CtlHdl	pha	ldx #HiliteControl	jsl ToolLocator	rts	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *DispDiskEasy	ProcName Export** Description:	Invalidates the disk-rect in the Easy Update window,*	causing the Window Update Proc (StandardDrawProc) to be called.** Inputs:	none (Expects volume name in CurrentVol)** Outputs:	none** External Refs:	Import DiskBtnCoords	Import DiskEasyCoords1	Import DiskEasyCoords2	Import StandardPort** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	lda StandardPort+2	; Reset the grafport	pha	lda StandardPort	pha	ldx #SetPort	jsl ToolLocator	pea DiskEasyCoords1>>16	pea |DiskEasyCoords1	ldx #InvalRect	jsl ToolLocator	pea DiskEasyCoords2>>16	pea |DiskEasyCoords2	ldx #InvalRect	jsl ToolLocator	pea DiskBtnCoords>>16	pea |DiskBtnCoords	ldx #InvalRect	jsl ToolLocator	rts	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *DispDisk2Update	ProcName Export** Description:	Erases the top of the Custom Install window and displays:*	"Disk to Update: <volume name>".** Inputs:	none (Expects volume name in CurrentVol)** Outputs:	none** External Refs:	Import Disk2Rect	Import Disk2Update	Import CurVolBottom	Import CurVolRect	Import CurrentVol	Import EraseUpdateRect	Import UpdateRect** Entry Points:	Entry DispCurrentVol** Description:	Erases only the <volume name> and replaces it with*	the contents of CurrentVol.** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	jsr EraseUpdateRect	; Set GrafPort and erase update rect	clc	; Calculate the pen	position	lda Disk2Rect+2	pha	lda Disk2Rect	adc #0008	pha	ldx #MoveTo	; Move the pen	jsl ToolLocator	pea Disk2Update>>16	pea |Disk2Update	ldx #DrawString	; Draw the string	jsl ToolLocator	bra DrawCurrentVolDispCurrentVol	inc CurVolBottom	; Fix "Bottom" to erase everything	pea CurVolRect>>16	pea |CurVolRect	lda #EraseRect	jsl ToolLocator	dec CurVolBottom	; Restore original "Bottom" valueDrawCurrentVol	clc	; Calculate the pen	position	lda CurVolRect+2	pha	; Horizontal position	lda CurVolRect	adc #0008	pha	; Vertical position	ldx #MoveTo	; Move the pen	jsl ToolLocator; DrawString tool can't handle GS/OS strings, so we must manually change; the string to a PStr and then change it back.	lda CurrentVol	xba	sta CurrentVol	pea CurrentVol+1>>16	pea |CurrentVol+1	ldx #DrawString	; Draw the string	jsl ToolLocator	lda CurrentVol	xba	sta CurrentVol	rts	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *DispDir2Update	Proc Export** Description:	Erases the top of the Installer window and displays:*	"Application folder: <pathname>".** Inputs:	none (Expects pathname in CurrentDir)** Outputs:	none** External Refs:	Import Dir2Rect	Import Dir2Update	Import CurDirBottom	Import CurDirRect	Import CurrentDir	Import EraseUpdateRect	Import UpdateRect* Entry Points:	Entry DispCurrentDir** Description:	Erases only the old <pathname> and replaces it with*	the contents of CurrentDir.** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	jsr EraseUpdateRect	; Set GrafPort and erase update rect	clc	; Calculate pen position	lda Dir2Rect+2	pha	lda Dir2Rect	adc #0008	pha	ldx #MoveTo	; Move the pen	jsl ToolLocator	pea Dir2Update>>16	pea |Dir2Update	ldx #DrawString	; Draw the string	jsl ToolLocator	bra DrawCurrentDirDispCurrentDir	inc CurDirBottom	; (So we can erase decenders.)	pea CurDirRect>>16	pea |CurDirRect	ldx #EraseRect	jsl ToolLocator	dec CurDirBottomDrawCurrentDir	clc	; Calculate pen position	lda CurDirRect+2	pha	lda CurDirRect	adc #0008	pha	ldx #MoveTo	; Move the pen	jsl ToolLocator	pea CurrentDir>>16	pea |CurrentDir	ldx #DrawString	; Draw the string	jsl ToolLocator	rts	EndP* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *EraseUpdateRect	Proc Export** Description:	Sets the GrafPort to the Custom Installation dialog's window and*	erases the top portion in preparation for redisplaying*	the Disk/volume to update information** Inputs:	none** Outputs:	none** External Refs:	Import DialogFlag	Import DialogPort	Import UpdateRect** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	bit DialogFlag	; Which dialog is running	bmi Exit	; ignore if Std Update	lda DialogPort+2	; Reset the grafport	pha	lda DialogPort	pha	ldx #SetPort	jsl ToolLocator	pea UpdateRect>>16	; Erase top of Installer window	pea |UpdateRect	ldx #EraseRect	jsl ToolLocatorExit	rts	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *GetCurDirPtr	Proc Export** Description:	Locks and dereferences <CurDirHdl placing the pointer*	into <CurDirPtr** Inputs:	none (Expects valid handle in <CurDirHdl.)** Outputs:	none (Places pointer to the current directory pathname,*	      a GS/OS Class 1 Output String, into <CurDirPtr)** External Refs:	Import MyZP** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	phd	; Need to return to REAL dPage	lda >MyZP	tcd	lda <CurDirHdl	; If handle is null, done	ora <CurDirHdl+2	beq Done	ldy #4	; Lock the handle	lda [<CurDirHdl],y	ora #attrLocked	sta [<CurDirHdl],y	lda [<CurDirHdl]	; Dereference the handle	sta <CurDirPtr	ldy #2	lda [<CurDirHdl],y	sta <CurDirPtr+2Done	pld	; Restore caller's dPage	rtl	EndP* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *GetAppDirPtr	Proc Export** Description:	Locks and dereferences <AppDirHdl placing the pointer*	into <AppDirPtr** Inputs:	none (Expects valid handle in <AppDirHdl.)** Outputs:	none (Places pointer to the current director pathname,*	      a GS/OS Class 1 Output String, into <AppDirPtr)** External Refs:	Import MyZP** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	phd	; Need to return to REAL dPage	lda >MyZP	tcd	lda <AppDirHdl	; If handle is null, done	ora <AppDirHdl+2	beq Done	ldy #4	; Lock the handle	lda [<AppDirHdl],y	ora #attrLocked	sta [<AppDirHdl],y	lda [<AppDirHdl]	; Dereference the handle	sta <AppDirPtr	ldy #2	lda [<AppDirHdl],y	sta <AppDirPtr+2Done	pld	; Restore caller's dPage	rtl	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *UnlockCurDirHdl	Proc Export** Description:	Marks <CurDirHdl as free to move.*	NOTE: Call with JSL!** Inputs:	none (Expects valid handle in <CurDirHdl.)** Outputs:	none** External Refs:	Import MyZP** Entry Points:** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	phd	; Need to return to REAL dPage	lda >MyZP	tcd	lda <CurDirHdl	; If handle is null, done	ora <CurDirHdl	beq Done	ldy #4	; Unlock the handle	lda [<CurDirHdl],y	and #$FFFF-attrLocked	sta [<CurDirHdl],yDone	pld	; Restore caller's dPage	rtl	EndP* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *UnlockAppDirHdl	Proc Export** Description:	Marks <AppDirHdl as free to move.*	NOTE: Call with JSL!** Inputs:	none (Expects valid handle in <AppDirHdl.)** Outputs:	none** External Refs:	Import MyZP** Entry Points:** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	phd	; Need to return to REAL dPage	lda >MyZP	tcd	lda <AppDirHdl	; If handle is null, done	ora <AppDirHdl	beq Done	ldy #4	; Unlock the handle	lda [<AppDirHdl],y	and #$FFFF-attrLocked	sta [<AppDirHdl],yDone	pld	; Restore caller's dPage	rtl	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *Concat	Proc Export** Description:	Concatenates a GStr onto the end of the current directory*	string found at <CurDirPtr.  The buffer is resized as needed.** Inputs:	Pointer to GStr to concatenate to current directory string*	Pointer to current directory buffer (to be concatenated)** Errors:	As returned by MemoryMgr and GSOString.lib.** External Refs:	Import GStrConcat	Import MyZP** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *DestBufferSize	equ $01	; Local variablesNeededSize	equ DestBufferSize+2Handle	equ NeededSize+2RtnAddr	equ Handle+4CurDir	equ RtnAddr+3	; Input parametersString	equ CurDir+4Variables	equ String; Provide space for local variables and make stack our D-page.	pha	pha	pha	pha	tsc	phd	tcd; Check if the final string will fit in the designated destination buffer.	lda [CurDir]	; Get the destination buffer size	sta DestBufferSize	ldy #0002	; Calculated the needed size	clc	lda [String],y	adc [CurDir],y	inc a	; Include the GStr buffer overhead	inc a	inc a	inc a	inc a	; one extra byte for trailing seperator	inc a	; one extra byte for trailing zero	sta NeededSize	cmp DestBufferSize	; How about it?	bcc ItFits	beq ItFits; It won't fit, so resize the memory before concatenating.;       Get the handle to the buffer	pha	pha	pei CurDir+2	pei CurDir	ldx #FindHandle	jsl ToolLocator	plx	; A-reg contains error code	ply	stx Handle	sty Handle+2	bcs Finished;       Unlock the memory (if its locked)	ldy #0004	; (faster than calling HUnlock)	lda [Handle],y	and #%0111111111111111 ; attrLocked = 0	sta [Handle],y;       Resize the buffer	pea 0000	pei NeededSize	pei Handle+2	pei Handle	ldx #SetHandleSize	jsl ToolLocator	bcs Finished;       Lock the buffer	ldy #0004	; (faster than calling HLock)	lda [Handle],y	ora #%1000000000000000 ;  attrLocked = 1	sta [Handle],y;       Dereference the handle and update the current directory pointer.	lda [Handle]	tax	ldy #0002	lda [Handle],Y	tay	stx CurDir	sty CurDir+2	phd	lda MyZP	; Also update <CurDirPtr	tcd	stx <CurDirPtr	sty <CurDirPtr+2	pld;       Store the new buffer size	lda NeededSize	sta [CurDir]; It will fit, so perform the concatenation.ItFits	pei String+2	pei String	pei CurDir+2	pei CurDir	pei CurDir+2	pei CurDir	jsl GStrConCat; Now, add the trailing seperator character followed by a null.  Then store; the incremented string length	ldy #0002	lda [CurDir],y	; Increment the length word	inc a	sta [CurDir],y	inc a	; Add on GStr overhead	inc a	inc a	tay	lda #SeparatorChar	sta [CurDir],y; Restore the environment	lda #0000Finished	sta OurErrorCode	pld	; Restore D-page	lda RtnAddr+1,s	; Move return address...	sta RtnAddr+9,s	;  ...past 8 bytes of inputs	lda RtnAddr,s	sta RtnAddr+8,s	tsc	;  ...and eliminate inputs & variables	clc	adc #Variables	; (bytes of inputs + variables)	tcs	lda OurErrorCode	; Restore the error code	cmp #0001	; Condition the cFlag	rtlOurErrorCode	ds.w 1	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *ResizeCurDirBuf	Proc Export** Description:	Resizes the buffer at <CurDirPtr so that it is exactly*	the right size to hold the string.  If the buffer is*	sized down, the c-flag is clear.  If the buffer is*	sized larger (the string wasn't all there) the c-flag*	is set.  <CurDirPtr is always updates with the new*	value, if any.** Inputs:	none (Expects valid pointer in <CurDirPtr)** Outputs:	c-flag clear: String is all there--buffer sized downward.*	c-flag set:   String not all there--buffer was sized*	              upward.  Try again.** External Refs:	Import GStrResize** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	pha	; Space for result	pha	pei <CurDirPtr+2	pei <CurDirPtr	jsl GStrResize	pla	sta <CurDirPtr	pla	sta <CurDirPtr+2	rtl	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *ResizeAppDirBuf	Proc Export** Description:	Resizes the buffer at <AppDirPtr so that it is exactly*	the right size to hold the string.  If the buffer is*	sized down, the c-flag is clear.  If the buffer is*	sized larger (the string wasn't all there) the c-flag*	is set.  <AppDirPtr is always updates with the new*	value, if any.** Inputs:	none (Expects valid pointer in <AppDirPtr)** Outputs:	c-flag clear: String is all there--buffer sized downward.*	c-flag set:   String not all there--buffer was sized*	              upward.  Try again.** External Refs:	Import GStrResize** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	pha	; Space for result	pha	pei <AppDirPtr+2	pei <AppDirPtr	jsl GStrResize	pla	sta <AppDirPtr	pla	sta <AppDirPtr+2	rtl	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *VolumesOnLine	ProcName Export** Description:	Marks flags to indicate that one or more volumes ARE on-line* 	Also opens root directory of target volume so a second*	volume of the same name on line will not screw up the user*	(installation to the wrong volume or something).** Inputs:	none** Outputs:	none** External Refs:	Import TargetIsOpen	Import InstallRemoveMode*	Export CloseTarget	Export NoVolumesOnLine	Export OpenTarget** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *; first close previous target's root directory (but only if it's already open)	jsr CloseTarget	jsr OpenTarget	; open target volume's root directory	lda InstallRemoveMode ; There ARE volumes on line	and #ÅbNoVols	; force NoVolumes flag to 0	bra FinishUp	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *NoVolumesOnLine	** Description:	Marks flags to indicate that there are NO volumes on-line* 	Also closes root directory of previous target volume.** Inputs:	none** Outputs:	none** External Refs:	Import NoVolumes	Import SetInstallRemove** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	jsr CloseTarget	sec	; Set the NoVolumes flag	ror NoVolumes	lda InstallRemoveMode	ora #bNoVolsFinishUp	sta InstallRemoveMode	jsr SetInstallRemove	rts* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *OpenTarget**External References:	Import CurrentVol** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *		jsl GSOS	dc.w Open	dc.l Open_Parm	bcs @done	lda OpenRefNum	sta CloseRefNum	sec	ror TargetIsOpen@done	rts* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *CloseTarget* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	lda TargetIsOpen	beq @NotOpen	jsl GSOS	dc.w Close	dc.l Close_Parm	stz TargetIsOpen@NotOpen	rts; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .;; GS/OS parameter tables and local storage;Open_Parm	dc.w 0002	; pCountOpenRefNum	dc.w 0000	; Reference NumberOpenPathname	dc.l CurrentVol	; Path Name PointerClose_Parm	dc.w 0001	; pCountCloseRefNum	dc.w 0000	; Reference Number	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *NewList2Call	Proc Export** Description:	Folder List:*	Makes a NewList2 tool call using variables maintained*	in lieu of a memory based ListRecord** Inputs:	none (Uses ListStart2, ListSize2, and AppFolderListHdl.** Outputs:	Returns ListMgr errors** External Refs:	Import DialogPort	Import AppFolderListHdl	Import ListSize2	Import ListStart2	Import PrintListMem	Import SelectListCtlHdl** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *; call NewList2 with the new list: start pushing parameters	pea PrintListMem>>16   ;drawPtr    (member drawing routine)	pea |PrintListMem	pea 0001	   ; listStart: start with item number 1); SortList2 unlocks AppFolderListHdl; so pass it as a pointer so it wonÕt be unlocked	ldx AppFolderListHdl+2	lda AppFolderListHdl	jsl DeRef	; Deref the hdl (already locked, but locks it)	phx	; listRef: push pointer to the new list	pha; push rest of params	pea 0000	; listRefDesc (listRef is a pointer)	lda ListSize2	; listSize	pha	lda SelectListCtlHdl+2 ; ctlHandle of list control returned by NewControl2	pha	lda SelectListCtlHdl	pha	ldx #NewList2	jsl ToolLocator; now sort the list	pea 0	; use standard comparison routine:	pea 1	;   do case insensitive sort ($0001)	lda SelectListCtlHdl+2 ; ctlHandle of list control	pha	lda SelectListCtlHdl	pha	ldx #SortList2	jsl ToolLocator	rts	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *PrintListMem	Proc Export** Description:	Folder List:*	PrintListMem will print a member of the Directory List*	when asked to do so by the ListMgrÑÑif, and only ifÑÑthe*	current script requires directory selection** Inputs: (on stack):*	Pointer to bounding rectangle*	Pointer to member record*	Handle to list control record (cannot be used: MemPtr overwrites it)** Outputs:	none** External Refs:	Import DirSelReq	Import Pattern** Entry Points:*	none** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *OrigD	equ 1	; (not used)RTLAdr	equ OrigD+2	; (not used)CHandle	equ RTLAdr+3	; (value not used; overwritten by string location)MemPtr	equ CHandle	; (overwrites CHandle)MemberPtr	equ CHandle+4	; (handle is locked) (drawing: Toolbox Ref p.11-5)RectPtr	equ MemberPtr+4; Save the registers and make the stack	our zero-page.	phd	; Save the direct register	tsc	; Make the stack...	tcd	;  ...our direct page	phb	; Save the bank register	phk	; Set the bank register...	plb	;  ...to where we are now; Does the current script require directory selection?	bit DirSelReq	bmi Start	brl Finished; need to access byte past end of string; used for disabled folder flagStart	ldy #0002	; get memPtr (ptr to string) from Member Record	lda [MemberPtr],y	sta MemPtr+2	; overwrite CHandleÕs storage location	lda [MemberPtr]	sta MemPtr; Clear whatever is	in the member's rectangle (in case it was previously; inverse and is now to become normal).	pei RectPtr+2	; Pointer to member's rectangle	pei RectPtr	ldx #EraseRect	; Erase the member's rectangle	jsl ToolLocator; Move the pen to the proper location	ldy #0002	; Calculate the horizontal position	lda [RectPtr],y	; Get the rectangle's 'LEFT' value	clc	;  and move over enough to make room	adc #0035	;  for the icon.	pha	ldy #0004	; Calculate the vertical position	lda [RectPtr],y	; Get the rectangle's 'BOTTOM' value	dec a	;  and back up two dots.	dec a	pha	ldx #MoveTo	; Move the pen	jsl ToolLocator; Determine whether	the list member is a subdirectory or something else, then; set up to show correct icon and print	name as active or inactive.	lda [MemPtr]	; get string length (lo byte)	and #$00FF	; get lo byte	inc a	; point to flag beyond end of string	tay	lda [MemPtr],y	bit #%0000000000000001 ; If bit 0=1, it's a disabled folder	bne InactiveFolder	ldy #0004	lda [MemberPtr],y	; Get the flags byte & one other byte	and #%0000000001000000 ; If bit 6=1, it's disabled (not folder)	beq ActiveFolder;       It's NOT a folder.  Set up to display the 'grayed-out' Document Icon	sec	; Set a flag to indicate that icon...	php	;  ...should be grayed-out.	pha	; space	pha	pea 0	; document icon by file type	pea $00	; file type of a document	pea 0	; aux type (ignore)	pea 0	ldx #GetSysIcon	; get system icon of folder	jsl ToolLocator	; leave icon pointer on the stack;               Print the Icon; Icon pointer already pushed	pea 0000	; Display mode	ldy #0002	; Calculate the horizontal position	lda [RectPtr],y	; Get the rectangle's 'LEFT' value	clc	;  and move over three dots.	adc #0001	pha		; Calculate the vertical position	lda [RectPtr]	; Get the rectangle's 'TOP' value	bra PrintIt;        It IS a folder!  Set up to display the folder Icon.ActiveFolder	clc	; Clear a flag to indicate that icon...	bra Folder	;  ...should appear active.InactiveFolder	sec	; Set a flag to indicate that icon...Folder	php	;  ...should be grayed-out.	pha	; space	pha	pea 0	; closed folder icon by file type	pea $0F	; file type of a folder	pea 0	; aux type (ignore)	pea 0	ldx #GetSysIcon	; get system icon of folder	jsl ToolLocator	; leave icon pointer on the stack;               Print the Icon; Icon pointer already pushed	pea 0000	; Display mode	ldy #0002	; Calculate the horizontal position	lda [RectPtr],y	; Get the rectangle's 'LEFT' value	clc	;  and move over three dots.	adc #0002	pha		; Calculate the vertical position	lda [RectPtr]	; Get the rectangle's 'TOP' value	inc aPrintIt	pha	ldx #DrawIcon	jsl ToolLocator; Print the string	pea -0008	; Horizontal displacement	pea 0000	; Vertical displacement	ldx #Move	; Back up eight dots	jsl ToolLocator	pei MemPtr+2	pei MemPtr	ldx #DrawString	jsl ToolLocator; If the item is NOT a folder, 'gray-out' the item	plp	; Restore the gray-it-out flag	bcc CheckSel	; bra if not to be grayed out; gray out the item	pea Pattern>>16	; Pointer to pen pattern	pea |Pattern	ldx #SetPenPat	; Set the pen pattern	jsl ToolLocator	pea $8001	; Indicate 'notOR'	ldx #SetPenMode	; Set pen mode	jsl ToolLocator	pei RectPtr+2	; Pointer to rectangle	pei RectPtr	ldx #PaintRect	; Paint the rectangle	jsl ToolLocator	ldx #PenNormal	; Restore normal pen	jsl ToolLocator	bra Finished	; That's all folks!!!;       Check to see if the entry is selected, and inverse it if it is.CheckSel	ldy #0004	lda [MemberPtr],y	; Get the flags byte & one other byte	and #%0000000010000000 ; If bit 7=1, it's selected	beq Finished	pea #$0000	; Color number	ldx #SetSolidPenPat	; Set the pen solid	pen pattern	jsl ToolLocator	pea $8002	; Indicate "notXOR"	ldx #SetPenMode	; Set pen mode	jsl ToolLocator	pei RectPtr+2	; Pointer to rectangle	pei RectPtr	ldx #PaintRect	; Paint the rectangle	jsl ToolLocator	ldx #PenNormal	; Restore normal pen	jsl ToolLocator; Restore registers, fix the stack, and	exitFinished	plb	; Restore the bank register	pld	; Restore the direct register	lda 1,S	; Move the return address up	sta 13,S	lda 2,S	sta 14,S	tsc	; Adjust the stack pointer	clc	adc #12	tcs	rtl	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *GetMemPointer	Proc Export** Description:	Folder List:*	Given a List2 (Folder selection list) member's item number,*	this call returns a pointer to the member's entry in the*	List.** Inputs:	A-reg contains member's item number** Outputs:	X and A-reg contain pointer to member's list entry** External Refs:	Import AppFolderListHdl	Import ListPointer2** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	dec a	; We're zero based, not "1" based	sta Temp; Dereference the handle to List2	lda AppFolderListHdl+2	pha	lda AppFolderListHdl	pha	jsl Dereference	pla	sta ListPointer2	pla	sta ListPointer2+2	lda Temp	asl a	asl a	clc	adc Temp	clc	adc ListPointer2	tax	lda #0000	adc ListPointer2+2	rtsTemp	ds.w 1	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *DrawNewList	Proc Export** Description:	Folder List:*	Forces the application folder selection List control*	to be re-drawn** Inputs:	none** Outputs:	none** External Refs:	Import SelectListCtlHdl** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	lda SelectListCtlHdl+2 ; ctlHandle	pha	lda SelectListCtlHdl	pha	ldx #DrawOneCtl	jsl ToolLocator	rts	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *OpenMsgWindow	Proc Export** Description:	Opens a window with no controls that can be used to let*	the user know what is going on when we're going to be busy*	for a while.** Inputs:	X and Y contain address of message string.** Outputs:	none** External Refs:	Import CursorArrowOn	Import CursorWatchOn** Entry Points:	Export CloseMsgWindow** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *; Message window height and width definitions.  (To change window size, change; these definitions only.  The window will be automatically centered.MsgHeight	equ 45MsgWidth	equ 320; Message window rectangle definition.MsgTop	equ 100-MsgHeight/2MsgLeft	equ 320-MsgWidth/2MsgBottom	equ 100+MsgHeight/2MsgRight	equ 320+MsgWidth/2; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; This routine is called by StartUp which is a dynamic segment which will; probably be running in another bank!  So set the environment for this; subroutine to guarantee it won't store data in unwanted locations.Begin	phb	; save caller's data bank	phk	plb; Get everything set up.  X and Y point to a LETextBox2 type string, prefixed; by a length word.	stx <ZPTemp	; Store the pointer	sty <ZPTemp+2	lda [<ZPTemp]	; Get the string length	sta textLength	inx	; Calculate position where string begins	bne @0	iny@0	inx	bne @00	iny@00	stx textPtr	sty textPtr+2	pha	; Space for result	pha	ldx #GetPort	; (Save current GrafPort)	jsl ToolLocator	; (and leave on stack)	jsr CursorWatchOn	; Switch to the "watch" cursor.; Open the window	pha	; Space for result	pha	pea StandByTemplate>>16 ; paramListPtr	pea |StandByTemplate	ldx #NewWindow	jsl ToolLocator	plx	; Get window's grafPortPtr	ply	stx StandByWindow	sty StandByWindow+2	phy	; Set the GrafPort	phx	ldx #SetPort	jsl ToolLocator; Draw the "talking head" icon	pha	; space for result	pha	pea rIcon	pea rIconNoteID>>16	pea |rIconNoteID	ldx #LoadResource	jsl ToolLocator	; handle of resource left on stack	jsl DeReference	; pointer to talking head icon left on stack	pea 0	; DisplayMode	pea 0010	    ; Horizontal position (LEFT)	pea 0004	    ; Vertical position (TOP)	ldx #DrawIcon	jsl ToolLocator; Display the message	lda textPtr+2	; textPtr	pha	lda textPtr	pha	lda textLength	; textLength	pha	pea TextRect>>16	; rectPtr	pea |TextRect	pea 0000	; just (left justified)	ldx #LETextBox2	jsl ToolLocator	ldx #SetPort	; (Restore the GrafPort)	jsl ToolLocator	; (pointer still on stack)	plb	; Restore caller's data bank	rtl; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; Routine to dispose of the window created above.CloseMsgWindow	phb	phk	plb	lda StandByWindow+2	pha	lda StandByWindow	pha	ldx #CloseWindow	jsl ToolLocator; Restore the arrow cursor.	jsr CursorArrowOn	plb	rtl	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; Local DataStandByTemplate	dc.w StandByEnd-*	     ; paramLength	dc.w %0010000000100000   ; wFrameBits (fAlert + fVis)	dc.l 00000000	     ; wTitle	dc.l 00000000	     ; wRefCon	dc.w 0000,0000,0000,0000 ; wZoom	dc.l 00000000	     ; wColor	dc.w 0000,0000	     ; wYOrigin, wXOrigin	dc.w 0000,0000	     ; wDataH, wDataW	dc.w 0000,0000	     ; wMaxH, wMaxW	dc.w 0000,0000	     ; wScrollVer, wScrollHor	dc.w 0000,0000	     ; wPageVer, wPageHor	dc.l 00000000	     ; wInfoRefCon	dc.w 0000	     ; wInfoHeight	dc.l 00000000	     ; wFrameDefProc	dc.l 00000000	     ; wInfoDefProc	dc.l 00000000	     ; wContDefProc	dc.w MsgTop,MsgLeft	     ; wPosition	dc.w MsgBottom,MsgRight	dc.l $FFFFFFFF	     ; wPlane	dc.l 00000000	     ; wStorageStandByEndtextPtr	ds.l 1	; LETextBox2 string pointertextLength	ds.w 1	; LETextBox2 string lengthtextRect	dc.w 0004	; LETextBox2 rectangle	dc.w 0065	dc.w MsgBottom-MsgTop-4	dc.w MsgRight-MsgLeft-10StandByWindow	ds.l 1	; GrafPort of the "Stand By..." window	EndP	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *Allocate	Proc Export** Description:	Allocates memory of requested size up to $FFFF.*	Block will not cross a bank boundary.** Inputs:	A-reg contains memory size to allocate** Outputs:	cFlag clear = no errors*	cFlag set = error,  A-reg contains error code*	X & Y contain handle of new memory segment.** External Refs:	Import MyID** Entry Points:	none** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	pha	; Room for result	pha	pea 0000	; Block size	pha	lda >MyID	; UserID (long addressing because may	pha	;         be called from StartUp.)	pea attrNoCross	; Attributes (don't cross boundary)	pea 0000	; Location pointer	pea 0000	ldx #NewHandle	jsl ToolLocator	plx	ply	rtl	EndP	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .scanDevices	ProcName Export;; Description:	Called during the main event loop to watch for disk;	insertions or removals.;; Inputs:	none;; Outputs:	cFlag:  Clear no errors;	        Set = error;	cursor: set to arrow before exit;; External Refs:	Import AddScripts	Import Alphabetize	Import CheckScript	Import D_Cont_Parms	Import D_Cont_DevNum	Import D_DeviceNum	Import DialogFlag	Import DirSelReq	Import NextThisDevice	Import NoVolumes	Import ScriptListBuilt	Import ScriptListCtlHdl; - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -		pha	; space for result	pha	pea $D000	; flags: scan devices, Volume call, inserts/ejects	pea 0	; devnum	ldx #HandleDiskInsert	jsl ToolLocator	plx	; devnum: device inserted or ignored	pla	; flags; any insertions or ejections?	txy	beq ScanDevDoneClr	; branch if no insertions or ejections	lsr a	; bit 0: 1=ejection	bcc Insertion; ejection occurred: was device ejected the current device?	cpx D_DeviceNum	; Compare against current device	bne ScanDevDoneClr	; Don't advance to next device unless		;   just removed disk was current disk.	jsr NextDevice1	; advance to next device	bra CheckList; insertion occurredInsertion	lsr a	; bit 1: 1=newly formatted	bcs @Init	; bra if just newly initialized;        previously initialized disk was inserted	lda NoVolumes	beq @PrevVols	; bra if vols previously on line;            it's the only disk online, so advance to it	phx	; save devnum	txa		jsr NextThisDevice	; advance to this device	plx	; retrieve devnum@PrevVols	txa	; pass devnum in a	jsr ckVolume	; get volume name to pass along in X/Y	bcs scanDevDoneErr	; bra if got an error!	ldx #VolNameBuffer	ldy #^VolNameBuffer;            it might have new scripts on it, to add to the list	bit ScriptListBuilt	; Check to see if there's list to update	bpl @2	jsl AddScripts	; volume name just inserted in X & Y	bvc @2	; Skip the rest if no scripts added.;            new scripts added to list!	jsl Alphabetize	; Re-alphabetize the list	bit DialogFlag	; (hi-bit clear: Customized Installation)	bmi @2	; bra if Easy Update;            script list is visible: update it	lda ScriptListCtlHdl+2 ; Redraw the script list control.	pha	lda ScriptListCtlHdl	pha	ldx #DrawOneCtl	jsl ToolLocator@2	bra CheckNone;        blank disk was inserted and user elected to initialize it@Init	txa	jsr NextThisDevice	; advance to this device;        if no disks previously online, update any deactivated buttons in CustomCheckNone	bit NoVolumes	bpl @1	stz NoVolumes	bit DialogFlag	; (hi-bit clear: Customized Installation)	bmi @1	; bra if Easy Update	jsr CheckScript	; else update controls@1; changed devices, so may have to update application selection window (right list)CheckList	jsr CursorArrowOn	; return to arrow cursor.;               If we're currently in Customized Installation and directory;               selection is required, we must also update the Application;               Folder Selection window.	bit DialogFlag	; (hi-bit clear: Customized Installation)	bmi ScanDevDoneClr	bit DirSelReq	; (hi-bit set: Directory selection needed)	bpl ScanDevDoneClr	jsl MakeNewList	; make new list of folders (right list)ScanDevDoneClr	clcscanDevDoneErr	ldx #0000	ldy #0000ScanDevDone	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .getD_INFO	; (Local subroutine);; Description:	Performs a GS/OS D_Info call.;; Inputs:	none;; Outputs:	none;; Uses:	parameters - D_Info parameter table; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	jsl GSOS	dc.w D_Info	dc.l parameters	rts; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .parameters	dc.w 8devNum	ds.w 1	;INPUT: Device number to get info about.	dc.l devNamedevInfo	ds.w 1	ds.b 10devID	ds.w 1	;OUTPUT: Device ID number.devName	dc.w 0035,0000	ds.b 31	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .ckVolume	; (Local subroutine);; Descriptions:	Check if there is a volume in the device.;; Inputs:	a = device number.;; Outputs:	Carry clear if OK, set if bad device number.; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; --- Make volume call to device ----------------------------------------	jsr getVolName	;Get volume name in device.	bcc ckVolumeExit	cmp #$11	;No more devices?	beq BadDevice	cmp #$28	;No floppy drive connected?	beq NoError	cmp #$2F	;No disk in 3.5" drive?	beq NoError	cmp #$52	;Was the disk initialized by another OS?	beq wrongOS	cmp #$27	;Disk never been initialized/No disk.	beq uninitialized	tax	;Some other error?	beq newDeviceNoError	clc	;Device number was OK.ckVolumeExit	rtsBadDevice		;Bad device error.; --- Formatted media of an unknown OS is inserted ---------------------wrongOS; --- Uninitialized	media inserted --------------------------------------uninitialized; --- New device on line -----------------------------------------------newDevice	sec	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .getVolName	; (Local subroutine);; Description:	Get volume name in a device;; Inputs:	a = device number.;; Outputs:	none; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; --- Get device name ----------------------------------------	sta devNum	;Pass device number.	jsr getD_INFO; --- Get volume name in device ------------------------------	jsl GSOS	dc.w Volume	dc.l getVol	bcc @1	cmp #DuplicateVolume	bne @1; If we reported a duplicate volume on-line, eject the disk and continue	lda parameters+2	; Get the device number	sta D_Cont_DevNum	;  and put in parameters	jsl GSOS	dc.w D_Control	dc.l D_Cont_Parms@1	rtsgetVol	dc.w 2	dc.l devName+2	;INPUT: Pointer to device name.volName	dc.l volNameBuffer	;INPUT: Pointer to output name buffer.volNameBuffer	dc.w 0036,0000	ds.b 0032	ENDP* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *CheckVolume	ProcName Export** Description:	Checks CurrentVol's characteristics and notifies*	the caller if it is locked or a non-ProDOS volume.** Inputs:	none.** Outputs:	cFlag set: GS/OS error.  A-reg contains GS/OS return code.*	cFlag clear:  No GS/OS errors.  A-reg contains zero*	nFlag set:  Current volume is locked.*	nFlag clear:  Current volume is unlocked.*	vFlag set:  Current volume is non-ProDOS format.*	vFlag clear:  Current folume is ProDOS format.** External Refs:		import CurrentVol	export VolTotalBlocks  ; for use by Install.asm:Amendments** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	ldx #CurrentVol	ldy #^CurrentVol; Initialize our flag	stz Flag; Check if the destination is write-protected.	stx GetDevNumName	; Set up pathname pointer	sty GetDevNumName+2;       Using the volume name, get the device number@1	jsl GSOS	dc.w Get_Dev_Num	dc.l GetDevNumParms	bcs Oops;       Using the device number, get the device name.	lda GetDevNumNum	sta D_Info_devNum	jsl GSOS	dc.w D_Info	dc.l D_Info_Parms	bcs Oops;       Using the device name, get the volume info	ldx D_Info_devName	ldy D_Info_devName+2	inx	; Change pointer from pointing to the	bne *+3	;   buffer size word, to pointing to	iny	;   the string's length word.	inx	bne *+3	iny	stx VolDevName	sty VolDevName+2	jsl GSOS	dc.w Volume	dc.l Volume_Parms	bcs Oops;       Now check for write-protection	lda VolCharacteristics	and #$0003	; write protection & read-only FST bits	beq @2	; bra if not write-protected (both are 0)	sec	ror Flag@2; Now check the file system;       Check the file system ID	lda VolFileSysID	cmp #ProDOSFileSys	beq Exit	lda Flag	ora #%0100000000000000	sta FlagExit	lda #0000	bit Flag	clc	rtlOops	jsl Error	rtl; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .GetDevNumParms	dc.w 0002	; pCountGetDevNumName	ds.l 1	; devName  (Volume name)GetDevNumNum	ds.w 1	; devNumD_Info_Parms	dc.w 0002	; pCountD_Info_devNum	ds.w 1	; devNum  (Device name)D_Info_devName	dc.l devName	; devNameVolume_Parms	dc.w 0007	; pCountVolDevName	dc.l devName+2	; devNameVolVolName	dc.l volName	; volNameVolTotalBlocks	ds.l 1	; totalBlocksVolFreeBlocks	ds.l 1	; freeBlocksVolFileSysID	ds.w 1	; fileSysID	ds.w 1	; blockSizeVolCharacteristics	ds.w 1	; characteristicsdevName	dc.w 35	ds.b 33volName	dc.w 35	ds.b 33Flag	ds.w 1	EndP* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *LoadDiskNames	Proc Export** Description:	load DiskName resources; if none, set StandardNo (goto Custom).*	* Inputs:	none** Outputs:	carry: error** External Refs:		import StandardNo** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	stz StandardNo	; initialize	pha	; Space for result	pha	pea rDiskNames ; resourceType	pea DiskNames>>16 ; resourceID	pea |DiskNames	ldx #LoadResource	jsl ToolLocator	plx	; handle of resource	ply	ror StandardNo 	; if can't find resource: set StandardNo	stx <DiskNamesHdl	;   use Custom only	sty <DiskNamesHdl+2	rts	EndP	End